quests[60254] = { id = 60254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvoller Fund: Tirna Scithe", description = "Die Gorm sind hinsichtlich ihrer Nahrung nicht wählerisch, solange sie keine Anima enthält. Im Bauch einer Gormkönigin, die seit vielen Generationen am Leben ist, kann sich eine erstaunliche Anzahl unzerstörbarer Artefakte finden lassen. Aus diesem Grund sehen wir das Durchsuchen des Kadavers einer Königin als Schatzsuche an.\n\nEine der größten Königinnen frisst sich gerade durch Tirna Scithe. Sie ist sicher prallvoll mit Wertgegenständen. Solltet Ihr einen ungewöhnlichen Fund machen, werden wir Euch gebührend zu entschädigen wissen.", sourceObjective = "Beschafft ungewöhnliche Mechanoidenteile von Tred'ova in den Nebeln von Tirna Scithe.", progress = "Ihr seht aus, als hättet Ihr Euch in Gormkadavern gesuhlt. Oder seht Ihr vielleicht einfach immer so aus?", completion = "Soweit ich weiß, haben wir in all unserer Zeit hier nur wenige vergleichbare Objekte wie dieses gefunden. Ob es einem Volk von Kreaturen oder Mechanoiden, die vor uns kamen, gehörte, oder ob diese immer noch existieren, entzieht sich unserer Kenntnis.\n\nDie metallischen Komponenten dieses Teils scheinen von der Bauart den Mauern um uns herum in Oribos zu ähneln. Aber wir haben so etwas noch nie in Bewegung in der Stadt gesehen.\n\nIch werde es in das Reliktelager für diese Art Mysterien legen. Wählt gern eine angemessene Belohnung aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[60255] = { id = 60255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvoller Fund: Die Andre Seite", description = "Mueh'zala existiert schon seit vielen Generationen, auch wenn die genaue Anzahl unbekannt ist. Sein Reich gilt uns allen weiterhin als Mysterium.\n\nAber wir sind immer an Möglichkeiten und Profiten interessiert. Ein Wesen seines Alters, seiner Macht und mit so vielen uralten Seelen in seinem Reich müsste eigentlich im Besitz eines Reliktes von unermesslicher Seltenheit sein.\n\n<Das Licht um Ta'lans Kopf herum flackert für einen Moment auf. Er scheint... aufgeregt zu sein?>\n\nTötet dieses törichte Wesen und bringt mir seine Geheimnisse, dann werde ich Euch eine üppige Belohnung zukommen lassen!", sourceObjective = "Beschafft eine seltsame Ritualmaske von Mueh'zala auf der Andren Seite.", progress = "Habt Ihr etwas Interessantes mitgebracht?", completion = "Die Gestaltung dieser Maske ähnelt einigen der Mechanoidenteile, die wir in unserer Zeit hier in den Schattenlanden gefunden haben. Vielleicht gehörte sie zu einer uralten Zivilisation? Leider gibt es nur weit verstreute und unvollständige Informationen darüber.\n\nAlle Teile dieser Art, die Ihr noch finden könnt, würden uns helfen, diese großen Mysterien aufzudecken. Bezüglich dieses Ortes scheint es einen größeren Zusammenhang zu geben, den wir, wie so viele andere Dinge, noch nicht erkennen können.\n\nIch nehme sie Euch gerne ab und biete im Tausch dafür einen unserer wertvollsten Gegenstände an.", sourceObjectiveStatus = "unverified-source-field" }
quests[60256] = { id = 60256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvoller Fund: Hallen der Sühne", description = "Die Aristokraten von Revendreth handeln untereinander mit dekadenten und unschätzbar kostbaren Prestigegegenständen, aber selten mit uns. Auf Reisen befestigen sie oftmals ein oder zwei solcher Gegenstände an ihrer Kleidung, um ihren Stand zu verdeutlichen.\n\nViele von ihnen haben sich mittlerweile Graf Denathrius angeschlossen und sich von den Bürgern der Schattenlande abgewandt. Sie müssen zweifelsohne aufgehalten werden.\n\nOhne Zweifel.\n\nUnd solltet Ihr in diesem Zusammenhang einiger ihrer Besitztümer habhaft werden, werde ich Euch einen großzügigen Handel anbieten.", sourceObjective = "Beschafft die goldene Energiekugel vom Obersten Kämmerer in den Hallen der Sühne.", progress = "Wie läuft der Kampf?", completion = "Das ist ja mal ein prächtiger Fund. Ein funktionsfähiges Teil der mysteriösen Maschinerie, die man in den Schattenlanden finden kann.\n\nSeht nur die aufwändige Machart der Kugel, und wie die enthaltene Energie durch ein Konstrukt gebannt zu werden scheint, das sich fast unserer Vorstellungskraft entzieht. Wer könnte ein solches Objekt hergestellt haben? Wo sind diese Leute jetzt?\n\nWir müssen sofort eine gründliche Untersuchung einleiten. Und wenn Ihr etwas Ähnliches findet, schaut gern wieder herein. Nehmt Euch eine Belohnung, bevor Ihr geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60257] = { id = 60257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wertvoller Fund: Die Blutigen Tiefen", description = "Generalin Kaal hat viele Feinde getötet und bewahrt in einem Beutel an ihrer Seite die Schädel derjenigen auf, die sie für ihre größten Triumphe hält. Natürlich haben nicht alle von ihnen Schädel, also ist der Inhalt des Beutels ein buntes Sammelsurium.\n\nWir haben gehört, dass irgendwo darin der Kopf von einem der Unsrigen ist. Wir wissen nicht, um wen es sich handelt, da wir nicht oft in Konflikt mit den Venthyr geraten.\n\nSolch ein seltsames Rätsel muss gelöst werden. Selbstverständlich werde ich für eine großzügige Entschädigung sorgen.", sourceObjective = "Beschafft ein uraltes Mittlerkopfstück von Generalin Kaal in den Blutigen Tiefen.", progress = "Welcherlei Informationen bringt Ihr mir?", completion = "Das ist nicht... was ich erwartet hatte.\n\nEs sieht aus wie einer von uns, und ist doch so anders. Gibt es noch andere unserer Art da draußen? Wer sind sie, und wo leben sie? Warum haben sie keinen Kontakt mit uns aufgenommen? Oder verstecken sie sich absichtlich?\n\nIst dies eine Geschichte, die wir kannten, aber vergessen haben? Ich habe so viele Fragen.\n\nIch danke Euch dafür, das ist sehr bedeutsam für uns. Bitte, nehmt ein mächtiges Relikt aus der Schatzkammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[60264] = { id = 60264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebende Seele", description = "Als Ihr mir im Ätherischen Gewölbe geholfen habt, wusste ich, dass Ihr <ein gerechter und würdiger Anführer/eine gerechte und würdige Anführerin> seid.\n\nIch bin gekommen, um Euch meine Hilfe und Dienste anzubieten, um Maldraxxus sein Gleichgewicht wiederzugeben.\n\nBitte baut ein Konstrukt für mich und erlaubt mir, Euch zu helfen, wie Ihr mir geholfen habt.", sourceObjective = "Nehmt die Spezifikationen für Mirus Konstrukt entgegen.", completion = "Miru ist eine sehr alte Seele und ein Überlebender. Es würde uns helfen, ihm ein Konstrukt zu bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60265] = { id = 60265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kette unterbrechen", description = "Vom Schreibtisch des Zehntherrn:\n\nAlle Versorgungskutschen müssen in die Steinwacht umgeleitet werden, um bei der Eintreibung zu helfen. Sobald diese abgeschlossen ist, dürfen die planmäßigen Routen fortgesetzt werden.", sourceObjective = "Zerstört die Dunkelhafenkutsche und die Kutsche des Anwesens in der Steinwachtwarte.", completion = "Gut gemacht.\n\nWir lassen diesen üblen \"Ernter\" ausbluten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60267] = { id = 60267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefängnis der Vergessenen", description = "<Als Ihr das gefundene Objekt anstarrt, spürt Ihr, dass es Euch zu einem anderen Teil dieses vermaledeiten Turms führen könnte.\n\nVielleicht weiß Ve'nari mehr über seinen Nutzen.>", sourceObjective = "Bringt das Objekt zu Ve'nari.", completion = "<Als Ihr den Schlüssel in das Gerät einsetzt, zittert es kurz und öffnet sich dann.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60268] = { id = 60268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief im Innern", description = "Wer... Wer seid Ihr? Wollt Ihr weitere meiner Erinnerungen extrahieren?\n\nIch befürchte, es sind keine nützlichen mehr übrig, außer den Erinnerungen an meine Gefangenschaft.\n\nOder vielleicht seid Ihr wegen etwas anderem hier?", sourceObjective = "Sprecht mit dem Gefangenen und erfahrt mehr über seine Situation.", completion = "Ihr könntet der Schlüssel zu meiner Freiheit sein. Werdet Ihr mir helfen, Sterblicher?", sourceObjectiveStatus = "unverified-source-field" }
quests[60269] = { id = 60269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedererwachen", description = "Wenn Ihr meine Erinnerungen zurückholen könnt, kann ich Euch helfen. Zumindest glaube ich das.\n\nDann können wir uns vielleicht gegenseitig helfen.", sourceObjective = "Findet eine gestohlene Erinnerung des Runenmetzes.", progress = "Habt Ihr gefunden, was mir genommen wurde?", completion = "Es ist ewig her, dass ich etwas anderes als die Umrisse dieses teuflischen Gefängnisses kannte.\n\nHabt Dank, Sterblicher. Nun zu der von Euch benötigten Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[60270] = { id = 60270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verfluchter Vertrag", description = "Ja... Allmählich erinnere ich mich. Macht. Macht mit einem Ziel. Das ist es, was ich anbieten kann.\n\nRunen. Runen sind der Schlüssel. Ich erinnere mich an einige von ihnen, aber um sie in Eure Ausrüstung einzubringen, benötige ich meine Hände.\n\nNun, eine Hand würde genügen. Beide wären besser.\n\nFindet einen Weg, mich von meinen Fesseln zu befreien, <Sterblicher/Sterbliche>. Dann kann ich Euch die Macht anbieten, die Ihr sucht. Danach die Freiheit... und vielleicht den Untergang desjenigen, der mich gefesselt hat.", sourceObjective = "Findet einen Weg, den Runenmetz von seinen Ketten zu befreien.", completion = "Die Ketten eines Gefangenen zerschlagen? Ich weiß nicht, wie man das bewerkstelligen könnte, außer...\n\nEs ist gefährlich, aber da gibt es einen Weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[60271] = { id = 60271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gravierende Chance", description = "Zuerst braucht Ihr ein Gefäß, um die Anima aufzunehmen, und eine Möglichkeit, sie auszustoßen. Ich besitze zufällig ein solches Gerät, das ich Euch gerne überlassen werde.\n\nFür einen Preis, versteht sich.\n\nIhr erinnert Euch doch an Zovaals Kessel? Die Bewohner dort wurden in unheiligem Feuer geschmiedet. Angenommen, ihre Anima ist von ähnlicher Natur, dann müsste sie sogar die Metalle des Turms schmelzen können.\n\nIch bin davon überzeugt, dass Ihr mit meinem Gerät und ihrer Anima Euer Ziel erreichen könnt, <Schlundgänger/Schlundgängerin>.", sourceObjective = "Kauft einen Animasuprifizierer von Ve'nari und besorgt 5 Einheiten geschmolzene Anima.", progress = "Konntet Ihr die Anima besorgen?", completion = "Euer Erfolg ist immer wieder beeindruckend, Schlundgänger.\n\nObwohl ich zugeben muss, dass derartige Heldentaten mich immer weniger überraschen, je besser ich Euch kennenlerne.", sourceObjectiveStatus = "unverified-source-field" }
quests[60272] = { id = 60272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das schwächste Glied", description = "Das sollte ausreichen, um die Bande zu lösen, die Euren neu gefundenen Verbündeten festhalten.\n\n<Ve'nari hält einen Moment inne.>\n\nBevor Ihr das tut, möchte ich ein Wort der Warnung aussprechen.\n\nMan sollte keinem Wesen vertrauen, das an diesem Ort gefangen ist. Seid vorsichtig, <Sterblicher/Sterbliche>.\n\nSchließlich wäre es eine Schande, einen so wertvollen Geschäftspartner zu verlieren.", sourceObjective = "Befreit den Runenmetz.", completion = "Freiheit. In gewisser Weise. Ja... das ist gut. Ich danke Euch.\n\nWas wolltet Ihr? Ah, Macht. Ja. Also gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[60274] = { id = 60274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handel und Wandel", description = "Willkommen, <mein Freund/meine Liebe>.\n\nIch erkenne an Eurem Gewand, dass Ihr eine recht geschichtsträchtige Vergangenheit haben müsst. Da sind viele einzigartige Relikte, die einer weitgereisten und kampferfahrenen Person angemessen sind.\n\nEs gibt diejenigen unter uns, die großen Wert auf solche Dinge legen und sich bereitwillig von ihren eigenen Wertgegenständen trennen würden, um einen Eindruck von dem zu bekommen, was Ihr finden könnt.\n\nLasst Euch von Eurer Neugierde zu dem dunklen Flur gegenüber der Kochtöpfe im Nebenraum leiten. Dort unten werdet Ihr Antworten finden.", sourceObjective = "Meldet Euch bei Finder Ta'sul in Oribos.", completion = "Ah, Ta'rella hat Euch wohl geschickt. Wir benötigen Eure Dienste.\n\nGlaubt mir, es wird Euer Schaden nicht sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60275] = { id = 60275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Vollstrecker Kristoff", description = "ACHTUNG!\n\nPatrouillen der Verhüllten haben im gesamten Glutdistrikt zugenommen. Auf Anordnung von Vollstrecker Kristof werden alle, die sich in der Nähe der Zuflucht befinden, gezwungen, das Licht zu ertragen.\n\nSeid äußerst achtsam, wenn Ihr Euch aus unserem Refugium hinauswagt. Selbst die Schatten sind nicht sicher, solange Kristof an der Macht bleibt.\n\nEine Belohnung wartet auf denjenigen, der den Distrikt von diesem Tyrannen befreit\n\n-Koordinatorin Raluca", sourceObjective = "Findet und tötet Vollstrecker Kristof.", completion = "Niemand wird Tränen über den Verlust eines solchen Schurken vergießen. Münzen gibt es in diesem Distrikt nicht gerade im Überfluss, aber nehmt dies. Der Besitzer ist schon lange tot und Ihr werdet einen fairen Preis dafür erzielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60276] = { id = 60276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Beschwörer Marcelis", description = "Seid gewarnt:\n\nBeschwörer Marcelis und seine Mitstreiter versuchen sich in gefährlicher Magie. Sie rufen Elementare aus Asche herbei, damit sie die vom Licht verbrannten Länder verwüsten.\n\nWir können derartige Handlungen nicht länger dulden.\n\nJeder, der sich dazu in der Lage sieht, wird aufgefordert, diesem Wahnsinn ein Ende zu bereiten.\n\n- Koordinatorin Raluca", sourceObjective = "Findet und tötet Beschwörer Marcelis.", completion = "Eure Belohnung, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60277] = { id = 60277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Aggregat des Unheils", description = "An alle Mitarbeiter:\n\nWir haben unten im Dickicht ein Problem.\n\nEin Golem wandert über die Baustelle und verursacht alle möglichen Probleme.\n\nSchnappt Euch 'nen Stein, und macht Euch ans schmeißen. Der Gräber, der ihn zur Strecke bringt, kriegt den Rest des Tages frei.\n\n- Vorarbeiter Scug", sourceObjective = "Findet und tötet das Aggregat des Unheils.", completion = "Ihr habt's also geschafft? Na gut. Dann können wir ja alle wieder an die Arbeit gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60278] = { id = 60278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Herzog Anton", description = "Treue Bürger von Revendreth:\n\nHerzog Anton und sein heruntergekommenes Haus sind Relikte der edlen Venthyrgesellschaft.\n\nSeine Versuche, meinen Namen zu beschmutzen, sind bestenfalls lachhaft.\n\nEs ist an der Zeit, dass jemand uns endgültig von Herzog Antons Anwesenheit befreit.\n\nIch werde das Doppelte der erbärmlichen Summe bieten, die er aufbringen kann.\n\nHochachtungsvoll,\n\nLord Darion vom Haus Redelav", sourceObjective = "Findet und tötet Herzog Anton vom Haus Dornfluch.", completion = "Haus Redelav hat ganz schön tief in die Tasche gegriffen. Aber ich schätze, Ihr habt es verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[60279] = { id = 60279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Der fahle Schrecken", description = "Hinweis für alle:\n\nIm Endmorast, gefährlich nahe der Grenze zu Dunkelhafen, lauert eine schleichende Bedrohung.\n\nIhr solltet darauf achten, dieser Monstrosität auf Euren Reisen auszuweichen, sonst findet Ihr den Tod.\n\nAbenteurern und einer gut bewaffneten Truppe könnte es gelingen, die Bestie zu töten. In dem Fall erwartet Euch bei Eurer Rückkehr eine Belohnung.\n\nHochachtungsvoll,\n\nZuchtmeister Gavril", sourceObjective = "Findet und tötet den fahlen Schrecken im Endmorast.", completion = "Ihr habt Dunkelhafen einen großen Dienst erwiesen, indem Ihr die Bestie getötet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60280] = { id = 60280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Lord Darion", description = "An alle Interessierten:\n\nLord Darion vom Haus Redelav denkt, dass er sich seinen Platz in der Gesellschaft erkaufen kann.\n\nEr stellt seinen Reichtum zur Schau und nutzt ihn, um die Gunst anderer Lords und Ladies zu gewinnen. Gibt es keinen Preis für Anstand?\n\nDies ist nicht die Art und Weise, wie sich die Adelshäuser von Revendreth verhalten sollten.\n\nIch flehe Euch an, Lord Darion zu finden und ihm zu seinem wahren Tod zu verhelfen.\n\nDie Ehre des Hauses Dornfluch ruht in Euren fähigen Händen.\n\nHerzliche Grüße,\n\nHerzog Anton von Haus Dornfluch", sourceObjective = "Findet und tötet Lord Darion vom Haus Redelav.", completion = "Das bedeutet hoffentlich, dass Haus Dornfluch das Gejammer einstellen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[60281] = { id = 60281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regel 4: Eine Liste machen", description = "Ich habe entdeckt, dass einer der Inquisitoren des Kerkermeisters versucht, eine Methode zu entwickeln, um meine Bewegungen zu verfolgen.\n\nDas ist eindeutig ein Problem für mich... und damit auch für Euch.\n\nDer Inquisitor ist auf meiner Liste möglicher Bedrohungen nach ganz oben geschossen. In der Vergangenheit hätte ich mich höchstpersönlich darum gekümmert. Aber jetzt... habe ich einen Geschäftspartner.\n\nBereitet ihm ein Ende, ja? Und falls möglich, findet heraus, wie genau er mich verfolgen wollte.", sourceObjective = "Tötet Inquisitor Devaki und findet heraus, wie er versucht, Ve'nari nachzuspionieren.", progress = "Habt Ihr etwas über Inquisitor Devakis Verfolgungsmethoden herausgefunden?", completion = "Gute Arbeit. Das sollte uns beide vor den Schlundgebundenen schützen.\n\nIch werde die Sphäre, die Ihr gefunden habt, behalten, um sie zu untersuchen.\n\nHabt Ihr nicht noch andere Verpflichtungen?", sourceObjectiveStatus = "unverified-source-field" }
quests[60283] = { id = 60283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespenst des Krieges: Visektus", progress = "Wir haben Visektus gerufen, um unseren Angriff anzuführen, aber wir brauchen Eure Hilfe, um ihn richtig vorzubereiten.\n\nWir benötigen weitere animagebundene Wickel, um die Beschwörungen zu verstärken.", completion = "Ich danke Euch, {name}. Eure Hilfe wird in unseren Aufzeichnungen festgehalten, damit die Nachwelt sie angemessen würdigen kann!" }
quests[60284] = { id = 60284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regel 5: Seid wagemutig", description = "Eure Mitarbeit hat sich als nützlich erwiesen, {class}. Zum Dank habe ich eine Chiffre entworfen, die es Euch erlaubt, weiter in den Schlund vorzudringen.\n\nSie hat allerdings... experimentellen Charakter. Ihr werdet sie in der Praxis erproben müssen. Und ich habe genau den richtigen Test im Sinn.\n\nDas Kartell Ve hat dummerweise weitere Agenten in den Schlund geschickt. Sie wurden gefangen genommen und in die Verdammnisfestung gebracht. Ich muss wissen, warum.\n\nBrecht in die Festung ein und bringt in Erfahrung, was aus den gefangenen Mittlern geworden ist. Nichts ist wertvoller als das Wissen um die Pläne Eures Feindes.", sourceObjective = "Untersucht die erhöhte Aktivität in der Verdammnisfestung.", completion = "Das Bestienlabyrinth, sagt Ihr... Ich frage mich, welche Ränke sie schmieden...\n\nEs ist so peinlich, das sie überhaupt erst entdeckt und gefangen genommen wurden. Es scheint, das Kartell Ve ist in meiner Abwesenheit ziemlich nachlässig geworden.\n\nIch bin Euch wie immer dankbar für Eure Hilfe. Ich werde Euch informieren, wenn ich Eure Dienste wieder benötige.", sourceObjectiveStatus = "unverified-source-field" }
quests[60285] = { id = 60285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regel 6: Tarnung ist alles", description = "Ich habe eine erschreckende Entdeckung gemacht, {name}.\n\nErinnert Ihr Euch, dass die gefangenen Agenten meines Kartells ins Bestienlabyrinth verschleppt wurden?\n\nDie Schlundgebundenen glauben offenbar, sie besäßen eine Möglichkeit, um mich zu verfolgen. Und jetzt ermächtigen seltsame neue Runen die Hunde des Kerkermeisters.\n\nDas können wir natürlich nicht zulassen.\n\nDiese neue Chiffre wird Euch Trost vor dem Kreischen im Bestienlabyrinth spenden. Wagt Euch in die Höhlen und bergt diese Runen, damit sie untersucht werden können,\n\nWenn wir ihren Auswirkungen entgegenwirken wollen, muss ich wissen, wie sie funktionieren.", sourceObjective = "Beschafft 15 Mittlerjagdrunen aus dem Bestienlabyrinth.", progress = "Die Runen... Habt Ihr sie?", completion = "Interessant... Runen, die Mittler mithilfe unserer extrahierten Essenz orten können.\n\nHoffen wir, dass Ihr die weitere Herstellung unterbinden konntet. Ich behalte diese, um sie weiter zu untersuchen.\n\nIrgendwann werdet Ihr mit Sicherheit wieder durch die alptraumhaften Ebenen des Bestienlabyrinths laufen müssen. Meine Chiffre wird Euch das ermöglichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60287] = { id = 60287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regel 1: Einen Fluchtplan haben", description = "Viele dem Untergang geweihte Seelen leiden im Schlund. Ihr müsst vorsichtig sein, wenn Ihr Euch nicht zu ihnen gesellen wollt.\n\nEuer Seelenbewahrer kann eine kleine Anzahl von Seelen festhalten, bis Ihr zu Eurem Pakt zurückkehrt. Aber das nützt Euch wenig, wenn Ihr selbst diesen Ort nicht überlebt.\n\nEs gibt eine Substanz, Stygia, die man bei einigen Geschöpfen im Schlund findet. Je stärker die Seele, desto mehr Stygia besitzt sie.\n\nSammelt etwas davon für mich, und ich kann daraus viele Dinge fertigen, die Ihr recht nützlich finden werdet.", sourceObjective = "Rettet 5 Seelen und holt 60 Stygia.\n\nStärkere Feinde haben eine höhere Chance, große Mengen Stygia zu verlieren.\n\nNutzt die Stygia, um von Ve'nari eine Chiffre des Rückzugs zu kaufen.", progress = "Ich helfe Euch gerne bei der Beschaffung von Überlebenswerkzeugen... vorausgesetzt, Ihr bringt mir Stygia.", completion = "Ihr scheint ein Händchen dafür zu haben, die Aufmerksamkeit des Kerkermeisters auf Euch zu lenken.\n\nDas ändert die Bedingungen unserer Vereinbarung.", sourceObjectiveStatus = "unverified-source-field" }
quests[60288] = { id = 60288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub von den Nekrolords", description = "{name}, danke für Eure Mühen. Unsere Truppen konnten dadurch weitere Ressourcen in unseren Kämpfen sicherstellen.\n\nJe deutlicher Ihr das Schlachtfeld beherrscht, desto mehr Ressourcen können unsere Truppen erübrigen.", sourceObjective = "Sprecht mit Oyne Seelenspross an der Düsteren Wehr in Maldraxxus, um Eure Belohnung zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60289] = { id = 60289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regel 3: Vertrauen will verdient sein", description = "Bevor Ihr dieses verfluchte Reich verlasst, gibt es eine letzte Aufgabe, die Ihr für mich erledigen müsst.\n\nDie Schlundgebundenen überführen regelmäßig Seelen aus vielen verschiedenen Gebieten im Schlund in verschiedene Blöcke von Torghast.\n\nIch kenne zufällig ein solches Gebiet. Stellt dieses Leuchtfeuer dort auf, damit ich informiert werde, wenn die nächste Überführung stattfindet.\n\nUnd wenn Ihr vom Feind gesehen werdet... nun, Ihr seid bekannt für Eure Tapferkeit im Kampf, ja?", sourceObjective = "Platziert ein Signalleuchtfeuer in Cocyrus.", progress = "Ich werde auch in Zukunft Handelsmöglichkeiten haben, Schlundgänger. Ich bin sicher, dass sich unsere Wege wieder kreuzen werden.", completion = "Einer Eurer Partner wurde nach Torghast gebracht?\n\nEs klingt, als hätte er sich ganz schön gewehrt. Vielleicht könnte er sich auch als nützlich erweisen... falls man ihn retten sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[60291] = { id = 60291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichenrückkehr", description = "Hier steht einiges an Arbeit an. Mmmmhmmm.\n\nHab einen riesigen Knochenkadaver in der Nähe gesehen. Ich will ein paar Teile davon nutzen.\n\nDachte, Ihr könnt mitkommen und mir helfen, das Ding zu Rathan zu bringen. Das wird ihm gefallen. Mmmmhmmm.\n\nIch könnte Euch glatt den ganzen Weg und wieder zurück tragen. Ihr seht gar nicht so groß aus.\n\nBereit für den Aufbruch?", sourceObjective = "Bringt den Knochenkadaver zu Rathan am Metzgerblock.", completion = "<Rathan schenkt Fliegenfalle einen beunruhigten Blick.>\n\nDas... Das ist... großartig!\n\nIch danke Euch beiden für diese Ressource!\n\n<Rathan lächelt Euch nervös an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60292] = { id = 60292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährlicher Gedankenaustausch", description = "Ich habe diese Schriftrolle gefunden, während Ihr den Tempel geläutert habt.\n\nEs sind düstere Worte, und ich befürchte, dass alles nur noch schlimmer wird. Sammelt noch mehr dieser Schriftrollen, damit ich herausfinden kann, was diese sogenannten Verschmähten vorhaben.", sourceObjective = "Sammelt 6 dunkle Predigten.", progress = "Wir müssen den Tempel beschützen, {name}.", completion = "Diese Worte...\n\nEs ist, wie ich vermutet habe.\n\n<Eridia starrt grimmig vor sich.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60296] = { id = 60296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rudel oder Einheit", description = "Ihr habt mit unserem Rudel große Fortschritte gemacht. Ich hoffe, Ihr habt in der Arbeit mit den Larion einen Wert und Erfüllung gefunden.\n\nJetzt wird es Zeit, dass wir uns mit Pelodis treffen. Ihr müsst entscheiden, wessen Lebensweise erfüllender ist und welchem Weg Ihr Euch anschließen möchtet.", sourceObjective = "Trefft Euch mit Pelodis und Nemea und entscheidet Euch für eine Seite.", completion = "Es ist vollbracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60313] = { id = 60313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schauerkuppe", description = "Das war knapp.\n\nAber ich glaube, dies ist eine Gelegenheit, endlich das Blatt in diesem Streit zu wenden und die Furchthetzerin zu besiegen. Wir treffen uns an der Schauerkuppe, der verlassenen Jagdhütte der Furchthetzerin.\n\nWir müssen getrennte Wege nehmen. Die Furchthetzerin wird sich bald wieder an unsere Fersen heften.", sourceObjective = "Sucht die Anklägerin an der Schauerkuppe auf.", completion = "Ich bin froh, dass Ihr es lebend bis hierher geschafft habt.\n\nGeneral Draven hat mir einen Plan geschildert, der vielleicht Erfolg haben könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[60315] = { id = 60315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schlingschnabel", description = "Dieb! Plünderer! Plagegeist!\n\nDiese niederträchtige Bedrohung namens Schlingschnabel ist eine Gefahr für unsere gesamte Ernte an Ambrosi und damit für unseren Tribut an die große Archon! Das muss ein Ende haben!\n\nWer auch immer dieses elende Federvieh zur Strecke und mir den entsprechenden Beweis bringt, wird reich belohnt. Das Nest der geflügelten Pest liegt am Westrand der Ernte der Erstgeborenen.\n\n- Gerdus", sourceObjective = "Besorgt Euch Schlingschnabels Schnabel für Gerdus in der Ernte der Erstgeborenen.", progress = "Was führt Euch in meine bescheidene Gesellschaft?", completion = "Unsere Ernte ist gerettet! Vielen Dank, tapfere Seele. Dann ist unser Tribut vielleicht doch noch nicht verloren!", sourceObjectiveStatus = "unverified-source-field" }
quests[60316] = { id = 60316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Veränderter Wächter", description = "Prätor kaputt! Am Prüfstein des Aspiranten. Greift alle an!\n\nIrgendwas falsch. Vielleicht geändert?\n\nSimo weiß nicht weiter. Hat alles versucht!\n\nMuss vernichtet werden!", sourceObjective = "Zerstört den veränderten Wächter für Hilfsschmied Simo in der Aspirantenrast.", completion = "Oh-hoh! Kaputter Prätor weg? Traurig. So traurig. Aber vielen Dank Eu-heuch!", sourceObjectiveStatus = "unverified-source-field" }
quests[60337] = { id = 60337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puppentruppen" }
quests[60338] = { id = 60338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Ardenwald", description = "Die Warnung, die Ihr vom Primus erhalten habt, muss die Winterkönigin des Ardenwalds erreichen, {name}. Die Ewigen müssen sich gemeinsam der heraufziehenden Dunkelheit stellen.\n\nDie Winterkönigin überwacht den Zyklus zwischen Tod und Leben. In ihrem Wald schlummern uralte Geister der Natur, die wiedergeboren werden müssen.\n\nIch befürchte, dass die Animadürre auf ihr Reich besonders bittere Auswirkungen hatte.\n\nDie Nachtfae können Euch zur Königin bringen. Überbringt ihr diese Botschaft und sie wird wissen, was zu tun ist.", sourceObjective = "Reist zum Ardenwald und findet jemanden, der Euch zur Winterkönigin bringt.", completion = "Wir haben schon lange niemanden mehr durch das Tor kommen sehen! Und schon gar nicht jemanden wie Euch.\n\nWas führt Euch zum Ardenwald?", sourceObjectiveStatus = "unverified-source-field" }
quests[60339] = { id = 60339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gluthof", description = "Prinz Renathal ist bereit, den heutigen Gluthof zu eröffnen, wenn Ihr es seid.\n\nSprecht unbedingt mit dem restlichen Personal, um die Gästeliste und Annehmlichkeiten fertigzustellen, bevor wir den Hof eröffnen.\n\nVergesst nicht, dass wir die Gäste beeindrucken und davon überzeugen wollen, dass wir wissen, was wir tun. Wählt also Ausstattung, die die Gäste zufriedenstellt!\n\nSprecht mit Lady Ilinca, wenn Ihr Fragen zu den Gästen habt.\n\nSobald alles bereit ist, sagt es mir, und ich eröffne den Hof!", sourceObjective = "Stellt Eure Gäste- und Ausstattungsauswahl für den Gluthof fertig, und gebt dann Euer Bestes, um die Gäste zu beeindrucken.", completion = "DAS war mal ein unvergesslicher Gluthof!\n\nWie wollt Ihr den nächste Woche überbieten?", sourceObjectiveStatus = "unverified-source-field" }
quests[60340] = { id = 60340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praktische Vorgehensweise", description = "Als ich im Ätherischen Gewölbe eingesperrt war, kamen die Animaschmarotzer, um mir das bisschen Kraft zu stehlen, das meine Seele noch hatte. Ich schwor, mich an ihnen zu rächen, sollte ich jemals fliehen.\n\nJetzt habe ich Klingen als Hände... Es ist Zeit für diese Rache!\n\nIch habe Animaschmarotzer in der Nähe des Hauses der Konstrukte gesehen. Ich will ihren Anführer tot sehen und die Anima zurück, die sie mir weggenommen haben!", sourceObjective = "Tötet Wurtzog Seelenraub und bergt 12 Animaspuren.", progress = "Habt Ihr sie alle getötet?", completion = "Guillotine kann grausam sein, aber manchmal erfordert die Situation genau das.", sourceObjectiveStatus = "unverified-source-field" }
quests[60341] = { id = 60341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erster Punkt der Tagesordnung", description = "Lasst uns eine Vereinbarung treffen, {name}. Ich werde die Winterkönigin in Eurem Namen aufsuchen, wenn Ihr Euch an meiner Stelle um einige Dinge kümmert. Die Königin ist nicht die Einzige, die durch diese Dürre schwer beschäftigt ist!\n\nZunächst werdet Ihr den Fae hier bei ihrem Problem mit den Spriggans aushelfen. Werft ihren Anführer von dieser armen Motte, dann wird Federleicht Euch sagen, wo Ihr danach hingehen müsst.\n\nSolltet Ihr überleben, treffen wir uns in Tirna Vaal wieder.\n\nOh, und ich an Eurer Stelle würde auf dem Weg bleiben. Der Ardenwald kann für Unvorsichtige gefährlich sein!", sourceObjective = "Tötet Mottenschreck den Mächtigen.", progress = "Nicht übel! Gar nicht übel!", completion = "Wenn Ihr mit Spriggans fertigwerden könnt, kann ich Euch vielleicht auch ein paar der interessanteren Aufgaben von Lady Mondbeeres Arbeitsplan übertragen. Ausgezeichnet!", sourceObjectiveStatus = "unverified-source-field" }
quests[60342] = { id = 60342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stutzt sie zusammen", description = "Untätige Hände sind eine vergeudete Chance. Ich muss meine Hände beschäftigen, sonst wären diese Klingen eine Verschwendung!\n\nMan sagte mir, es gäbe einen Verschlinger in Revendreth, der haushoch aufragt. Lasst uns den anderen Konstrukten das eine oder andere zeigen, indem wir das Monster ausschalten!", sourceObjective = "Tötet Charthox im Gräberwald von Revendreth.", completion = "Gute Arbeit! \n\nGuillotines Anstrengungen sind nicht unbemerkt geblieben, und ich habe gesehen, dass die anderen ihre Anstrengungen verdoppeln, um ihrem Beispiel zu folgen.\n\nHabt nochmals Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[60343] = { id = 60343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Orgrimmar", description = "Ich muss meinen Missionsbericht über die Insel des Verbannten unverzüglich an den Kriegshäuptling überbringen.\n\nCork Blubberplopp wird Euch in der Zwischenzeit die Stadt zeigen. Orgrimmar hat viel zu bieten, also erkundet alles in Ruhe.\n\nIch werde nach Euch rufen lassen, sobald ich dem Kriegshäuptling berichtet habe.", sourceObjective = "Trefft Euch mit Cork Blubberplopp am Stadttor.", completion = "Hey, {name}! Lange nicht gesehen, oder?\n\nKriegsherrin Grimmaxt hat mich gebeten, Euch hier alles zu zeigen. Also los!", sourceObjectiveStatus = "unverified-source-field" }
quests[60344] = { id = 60344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orientierung", description = "Orgrimmar ist eine große Stadt. Viel zu groß, um alles zu Fuß zu erkunden. Kriegsherrin Grimmaxt hat dafür gesorgt, dass Ihr ein Reittier erhaltet, um besser herumzukommen.\n\nSie hat gesagt, Ihr sollt mit Rohaka bei den Ställen sprechen... aber mir fällt der Weg dorthin gerade nicht ein.\n\nKeine Sorge, {name}! Wir müssen nur eine Wache nach der Wegbeschreibung fragen. Wenn Ihr den Weg nicht kennt, werden Euch die Stadtwachen helfen.\n\nErkundigen wir uns doch bei einer Wache in der Nähe, wie wir zum Stallmeister kommen, damit wir endlich losziehen können!", sourceObjective = "Sprecht mit Rohaka Hammerhauer bei den Ställen.", completion = "Kriegsherrin Grimmaxt hat mich damit beauftragt, Euch ein Reittier zu besorgen, aber wir müssen zunächst etwas anderes erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60345] = { id = 60345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lizenz zum Reiten", description = "Kriegsherrin Grimmaxt hat schon gesagt, dass Ihr Euch heute ein Reittier aus den Ställen holen werdet.\n\nAber bevor Ihr gleich in die Schlacht stürmt, braucht Ihr erst mal ein paar Reitstunden.\n\nSprecht mit Kildar, wenn Ihr lernen wollt, wie man reitet.", sourceObjective = "Sprecht mit Kildar, um die Fähigkeit 'Unerfahrenes Reiten' zu erlernen.", completion = "Nachdem Ihr jetzt die Grundlagen erlernt habt, kommt einfach jederzeit wieder, wenn Ihr Eure Reitkünste verbessern oder ein weiteres Reittier kaufen wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[60346] = { id = 60346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Telotha Pinienhain über die Spezialisierungen!", sourceObjective = "Sprecht mit Telotha Pinienhain, um mehr über Kampfspezialisierungen zu erfahren.", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[60347] = { id = 60347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Tamanji über die Spezialisierungen!", sourceObjective = "Sprecht mit Tamanji, um mehr über Kampfspezialisierungen zu erfahren.", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
