quests[60355] = { id = 60355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Kazak Dunkelschrei über die Spezialisierungen!", sourceObjective = "Sprecht mit Kazak Dunkelschrei, um mehr über Kampfspezialisierungen zu erfahren.", progress = "Seid gegrüßt. Möchtet Ihr mehr über Kampfspezialisierungen erfahren?", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[60357] = { id = 60357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Gormok Ogerfaust über die Spezialisierungen!", sourceObjective = "Sprecht mit Gormok Ogerfaust, um mehr über Kampfspezialisierungen zu erfahren.", progress = "Seid gegrüßt. Möchtet Ihr mehr über Kampfspezialisierungen erfahren?", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[60358] = { id = 60358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Güldenitrausch", description = "Hat unser Güldenit! Gestohlen! Gestohlen und mitgenommen!\n\n<Sika schüttelt ihr Gefieder.>\n\nIst wichtig, ist wichtig für Rüstungen! Waffen!\n\nKein Güldenit, keine Rüstung!\n\n<Sika bewegt ihre Arme, als würde sie eine Rüstung anfertigen.>\n\nVerstanden? Ja? Und trotzdem noch hier?", sourceObjective = "Sammelt 3 Stücke Güldenit von seltenen Monstern und Schatztruhen in der Bastion.", sourceObjectiveStatus = "unverified-source-field" }
quests[60359] = { id = 60359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuhause ist, wo man seine Ruhe hat", description = "Ich weiß ja nicht, wie es Euch geht, aber ich hätte Lust auf ein nettes kleines Ruhepäuschen!\n\nWarum genehmigen wir uns nicht im Wyvernschweif ein paar große Gläser Cobo Cola?\n\nUnd wenn wir schon da sind, sprecht mal mit der Gastwirtin Nufa, um den Wyvernschweif zu Eurem neuen Zuhause zu machen. Solltet Ihr in Zukunft mal ohne Flugmeister dastehen, könnt Ihr dann mit Eurem Ruhestein direkt ins Gasthaus zurück.\n\nDas ist nicht nur schneller als ein Wyvern, sondern spart Euch auch ein paar Münzen!", sourceObjective = "Sprecht mit Gastwirtin Nufa, um das Gasthaus \"Zum Wyvernschweif\" als Euren Heimatort festzulegen.", progress = "Wie kann ich Euch heute helfen, {class}? Sucht Ihr nach einer Bleibe?", completion = "Solange der Wyvernschweif Euer Heimatort ist, werdet Ihr bei Eurer Rückkehr hier ein wärmendes Feuer vorfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60360] = { id = 60360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wichtiges Treffen", description = "Ich habe in ganz Orgrimmar nach Euch gesucht, {name}.\n\nKriegsherrin Grimmaxt hat dem Kriegshäuptling ihren Missionsbericht vorgelegt. Die Horde benötigt erneut Eure Dienste.\n\nIch habe Befehl, Euch unverzüglich zu finden und diese Nachricht zu überbringen. Es war mir eine Ehre, an Eurer Seite zu kämpfen, {name}.\n\nLok'tar Ogar!", sourceObjective = "Sprecht mit Kriegsherrin Breka Grimmaxt in der Feste Grommash.", completion = "Da seid Ihr ja endlich. Der Kriegshäuptling will Euch sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60361] = { id = 60361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Missionsrichtlinie", description = "Der Kriegshäuptling will Euch persönlich sehen.\n\nLady Sylvanas war von Eurer Tapferkeit während unserer Mission auf der Insel des Verbannten tief beeindruckt.\n\nDa Ihr jetzt da seid, werde ich Euch vorstellen.", sourceObjective = "Nehmt am Kriegsrat in der Feste Grommash teil.", completion = "Die Dunkle Fürstin hat ihr Vertrauen in uns gelegt. Wir werden nicht versagen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[60362] = { id = 60362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leer", description = "Kul Tiras besitzt die größte Seestreitmacht von Azeroth und ist ein früherer Verbündeter. Aber leider haben wir kaum noch Kontakt zu ihnen, seit Jainas Vater, Lordadmiral Daelin Prachtmeer, in Theramore besiegt wurde.\n\n\n\nViele haben Jainas Entscheidung damals verurteilt und meinten, sie wäre von der Aussicht auf einen Frieden zwischen Allianz und Horde so überzeugt gewesen, dass sie ihren eigenen Vater verraten hat.\n\n\n\nVielleicht spürt sie jetzt, dass die Zeit gekommen ist, Wiedergutmachung zu leisten.\n\n\n\nSo sehr ich die Vorstellung hasse, Jaina einer Gefahr auszusetzen... Kul Tiras muss sich der Allianz anschließen.\n\n\n\nViel Glück.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer im Hafen von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[60363] = { id = 60363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Güldenitrausch", description = "Kzzz... Das goldene Erz. Wir brauchen es.\n\nGoldenes Erz der Bastion. Ist für ihre Rüstungen.\n\nWir brauchen das. Viel Verwendung. Rüstung, Waffen, Schmuck und Ringe. Viele Möglichkeiten.\n\nGeht zur Bastion. Große Haufen haben die Augen gesehen, gestohlen und versteckt im ganzen Land.\n\nKeiner da nutzt es. Wir wollen es. Geht jetzt.", sourceObjective = "Sammelt 3 Stücke Güldenit von seltenen Monstern und Schatztruhen in der Bastion.", sourceObjectiveStatus = "unverified-source-field" }
quests[60364] = { id = 60364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Güldenitrausch", description = "Unsere Verbündeten in der Bastion besitzen ein besonderes Erz namens Güldenit. Ein goldenes Metall, das dort für viele Dinge verwendet wird. Auch wir könnten es gut gebrauchen.\n\nVor langer Zeit haben wir es auf dem Handelswege erworben, aber jetzt haben wir nichts zum Tauschen und sie kaum etwas anzubieten.\n\nAber für unsere Zauber ist es unverzichtbar, da es magische Energie bündelt und verstärkt.\n\nSolltet Ihr auf Euren Reisen etwas davon sehen, nehmt es ruhig mit und bringt es mir. Ich nehme, was wir brauchen, und teile den Rest.", sourceObjective = "Sammelt 3 Stücke Güldenit von seltenen Monstern und Schatztruhen in der Bastion.", sourceObjectiveStatus = "unverified-source-field" }
quests[60365] = { id = 60365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Güldenitrausch", description = "Das als Güldenit bekannte goldene Erz gibt es nur in der Bastion. Sie stellen dort Rüstungen daraus her, aber alle können es gut gebrauchen. Wir härten damit unsere Rüstungen und Waffen und es ist hervorragend geeignet, um magische Energie zu speichern.\n\nUnsere Vorräte sind fast erschöpft und wir haben nichts zum Tauschen. Aber wir brauchen dringend Nachschub.\n\nDenken wir doch einmal logisch.\n\nIn der Bastion gibt es einige, die ihr eigenes Volk verraten haben.\n\nDiese falschen Schlangen um ihr Güldenit zu bringen, ist wirklich kein Grund zur Reue.", sourceObjective = "Sammelt 3 Stücke Güldenit von seltenen Monstern und Schatztruhen in der Bastion.", sourceObjectiveStatus = "unverified-source-field" }
quests[60366] = { id = 60366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Nachtflügel", description = "Die Wolkenfedermatriarchin Nachtflügel leidet an einer furchtbaren Krankheit. Sie wird immer aggressiver, unterdrückt ihre Kinder und treibt sie zur Gewalt an.\n\nNachtflügel muss sterben, wenn ihre Brut je wieder die Gunst der Archon erlangen will.\n\nRuft sie mit der beigefügten Pfeife zu ihrem Nest. Eine ihrer Kronfedern genügt mir als Beweis für die vollbrachte Tat.\n\n- Stallmeisterin Eumelia", sourceObjective = "Besorgt im Großschwingenhorst eine Umbralfeder von Nachtflügel für Eumelia.", progress = "Bis Nachtflügel endlich Ruhe findet, wird ihre Brut keinen Frieden haben.", completion = "Meinen Dank, dass Ihr das Gleichgewicht dieser faszinierenden Wesen wiederhergestellt habt. Jeder von uns hat seine Rolle zu spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60367] = { id = 60367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bastionsbesuch" }
quests[60369] = { id = 60369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilder Waldholzwahn", description = "Die Former unseres Landes bauen eine ganz besondere Holzart an, die wir Waldholz nennen.\n\nEs enthält die Essenz des Ardenwalds... der Pflanzen und Tiere, die unser Erdreich und unsere Luft ausmachen. Es kann mit mächtiger Magie verzaubert werden und brennt nicht.\n\nEs ist die Grundlage für unsere Waffen und Rüstungen, und in diesen finsteren Tagen ist es das Ziel unserer Feinde.\n\nSie stehlen und horten es in der Wildnis da draußen.\n\nFindet sie und bringt unsere Schätze zu uns zurück.", sourceObjective = "Sammelt 3 Stücke Waldholz von seltenen Monstern und Schatztruhen im Ardenwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[60370] = { id = 60370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilder Waldholzwahn", description = "Im Ardenwald bilden die Former aus Ästen und Zweigen eine magische Holzart. Waldholz ist eine verzauberte Substanz, die für viele Zauberzwecke eingesetzt wird und ein Schlüsselelement in unseren Ritualen ist.\n\nOhne Waldholz verblasst unsere Magie im Vergleich zu der unserer Widersacher.\n\nDoch in diesen Zeiten ist der Ardenwald von vielen Feinden befallen. Sie stehlen die Vorräte der Nachtfae und huschen zu finsteren Orten davon.\n\nBegebt Euch an diese Orte und kehrt zu uns zurück, nachdem Ihr diese abscheulichen Kreaturen büßen ließt.", sourceObjective = "Sammelt 3 Stücke Waldholz von seltenen Monstern und Schatztruhen im Ardenwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[60371] = { id = 60371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilder Waldholzwahn", description = "Die Augen haben mir Vorräte gezeigt, im Ardenwald. Versteckt in den Ästen, versteckt vor uns, aber nicht versteckt vor den Augen.\n\nSie verwenden es nicht, nicht so, wie wir es tun. Wir müssen es verwenden. Es gehört uns.\n\nKshhh... bringt es uns, das geformte Holz. Hat vielen Nutzen, sehr magisch. Enthält Magie wie ein Krug Schleim enthält, ist damit gefüllt.\n\nBrauchen es für unsere Zauberer. Können im Kampf nicht ohne unsere Magie gewinnen. Müssen gewinnen, geht nicht anders.", sourceObjective = "Sammelt 3 Stücke Waldholz von seltenen Monstern und Schatztruhen im Ardenwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[60372] = { id = 60372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilder Waldholzwahn", description = "Ardenwald in Schwierigkeiten! Wir auch in Schwierigkeiten! Kein Ardenwald, kein Waldholz!\n\nWaldholz magisch, gut für viele Dinge.\n\nIhr findet Waldholz? Bringt es Sika? Ja? Huuh?\n\nJa.\n\n<Sika schreibt Euren Namen auf eine Schriftrolle, unterstreicht ihn doppelt und zeigt sie Euch.>\n\nGesehen?", sourceObjective = "Sammelt 3 Stücke Waldholz von seltenen Monstern und Schatztruhen im Ardenwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[60373] = { id = 60373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trauerrankenspiel", description = "Es gibt eine finstere, böse Kletterranke, die in Revendreth wächst und als Trauerranke bekannt ist.\n\nMan sagt, sie nährt sich an der Angst der Seelen, wenn sie gebrochen werden.\n\nGanz gleich, wo sie herstammt, sie wird in vielen unserer Tränke und Zauber verwendet. Sie enthält mächtige Magie, wahrscheinlich ein Ergebnis ihres Ursprungs.\n\nRevendreth hat heutzutage nur wenig Gelegenheit, mit uns zu handeln. Solltet Ihr diese Kletterranken finden, werde ich sie Euch gerne abnehmen.", sourceObjective = "Sammelt 3 Stücke Trauerranke von seltenen Monstern und Schatztruhen in Revendreth.", sourceObjectiveStatus = "unverified-source-field" }
quests[60374] = { id = 60374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenmetallkrise", description = "Die Einwohner von Maldraxxus sind an ein Leben voller Kämpfe gewöhnt und besitzen daher viele Knochen.\n\nSie stellen ihre Rüstung aus einer kultivierten Knochenart her, die wir Knochenmetall nennen. Es ist härter als die meisten Metalle und doch biegsam. Deshalb kann es beim Schmieden in verschiedene Formen gebracht werden, ohne seine Stärke zu verlieren.\n\nEs gibt vielfältige Nutzungsmöglichkeiten, beispielsweise für Befestigungen oder gemahlen als Reagenz.\n\nWir können sie jetzt nicht um Ressourcen bitten, aber wenn Ihr es findet, würde ich es verwenden.", sourceObjective = "Sammelt 3 Stücke Knochenmetall von seltenen Monstern und Schatztruhen in Maldraxxus.", sourceObjectiveStatus = "unverified-source-field" }
quests[60375] = { id = 60375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenmetallkrise", description = "Unsere Rufe verhallen von Maldraxxus ungehört und in den Häusern herrscht Chaos.\n\nDoch wir brauchen sie. Einst versorgten sie uns mit Knochenmetall, einem starken, aber formbaren Material, das für viele Rüstungen nützlich ist.\n\nEinige in Maldraxxus horten das Material und versuchen, aus dem Chaos Nutzen zu ziehen.\n\nSie müssen für diese Sünden büßen.", sourceObjective = "Sammelt 3 Stücke Knochenmetall von seltenen Monstern und Schatztruhen in Maldraxxus.", sourceObjectiveStatus = "unverified-source-field" }
quests[60376] = { id = 60376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenmetallkrise", description = "Ksh-ksh-ksh... Ihr werdet gebraucht.\n\nSo viele Verräter in unserem Land, viele Tode, viel zerstörte Rüstung. \n\nMuss repariert werden.\n\nDie Augen haben mir Lager voller Knochenmetall gezeigt, das unsere Feinde horten.\n\nBringt es zu mir.", sourceObjective = "Sammelt 3 Stücke Knochenmetall von seltenen Monstern und Schatztruhen in Maldraxxus.", sourceObjectiveStatus = "unverified-source-field" }
quests[60377] = { id = 60377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenmetallkrise", description = "<Sika studiert eine Schriftrolle.>\n\nKein Knochenmetall! Schon wieder alle!\n\n<Sika wirft einen Haufen Schriftrollen in die Luft.>\n\nHuuh! Was denn jetzt?\n\nOh, OH. Knochenmetall! Holt Ihr? Von Maldraxxus. Hilft uns viel!\n\n<Sika zeigt in die Richtung von Maldraxxus.>\n\nDa lang!", sourceObjective = "Sammelt 3 Stücke Knochenmetall von seltenen Monstern und Schatztruhen in Maldraxxus.", sourceObjectiveStatus = "unverified-source-field" }
quests[60378] = { id = 60378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trauerrankenspiel", description = "Die Trauerranke wächst nur hier, in der Tiefebene von Revendreth. In ihren Blättern und Samen ist eine Kraft enthalten, die vielleicht ein Nebenprodukt der Reinigung von Sünden ist.\n\nWir verwenden sie für viele Dinge, von Tränken bis hin zu Giftstoffen. Sie ist ein vielseitig verwendbares Reagenz.\n\nUnsere Vorräte sind knapp und wir haben heutzutage kaum noch Gelegenheit, sammeln zu gehen, da die Streitkräfte unserer Feinde über uns herfallen.\n\nSolltet Ihr während Eurer Reisen durch unser Land zufällig auf welche stoßen, könnten wir sie gut gebrauchen.", sourceObjective = "Sammelt 3 Stücke Trauerranke von seltenen Monstern und Schatztruhen in Revendreth.", sourceObjectiveStatus = "unverified-source-field" }
quests[60379] = { id = 60379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trauerrankenspiel", description = "Kshh... brauche Euch heute. Lager mit Trauerranke sind fast leer, brauchen sie für unsere Giftstoffe.\n\nRevendreth antwortet uns nicht mehr. Die Augen zeigen mir Konflikt und Zwietracht und ihren Landen.\n\nDas betrifft uns nicht.\n\nShh... Reist dorthin, findet ihre Ranken, kehrt zurück zu mir.", sourceObjective = "Sammelt 3 Stücke Trauerranke von seltenen Monstern und Schatztruhen in Revendreth.", sourceObjectiveStatus = "unverified-source-field" }
quests[60380] = { id = 60380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trauerrankenspiel", description = "Keine Trauerranke mehr! Bitte helfen!\n\nRevendreth schickt keine Vorräte, keine Antwort an Sika! Keine Ranke, keine Tränke! Und jetzt?\n\n<Sika scheint gerade aufzugehen, dass Ihr dort wart.>\n\nIhr geht!\n\n<Sika schubst Euch.> \n\nGeht, geht!", sourceObjective = "Sammelt 3 Stücke Trauerranke von seltenen Monstern und Schatztruhen in Revendreth.", sourceObjectiveStatus = "unverified-source-field" }
quests[60381] = { id = 60381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Ardenwald", description = "Heute müssen wir unseren Blick nach innen richten. Die Feinde belagern uns hier im Ardenwald von allen Seiten.\n\nReist mit der Waffe in der Hand durch unser Land und bringt Hoffnung und Sieg. Helft den Bedürftigen und erinnert sie daran, dass wir für sie da sind und dass der Ardenwald nicht fallen wird.\n\nErinnert sie daran, dass unser großer Zweck erfüllt werden wird und dass wir die Haine nicht verkümmern lassen werden.\n\nIhr, <Schlundgänger/Schlundgängerin> werdet uns heute einen.", sourceObjective = "Schließt 3 Weltquests im Ardenwald ab.", completion = "Eure Taten heute haben unsere Bande gestärkt und unsere Wurzeln graben sich tiefer in den Boden als je zuvor. Wir werden uns des Ansturms der Feinde, die uns plagen, erwehren, da die Haine sich dank Euch zur Verteidigung miteinander verflechten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60382] = { id = 60382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Revendreth", description = "Wir kehren unseren Verbündeten nicht den Rücken, auch dann nicht, wenn wir uns hier im Ardenwald der Dunkelheit gegenübersehen.\n\nIn Revendreth wird gegen die Streitkräfte von Graf Denathrius gekämpft, der sich als betrügerischer Anführer erwiesen hat.\n\nWir dürfen nicht zulassen, dass diejenigen, die Sündensturz ihr Zuhause nennen, die Hoffnung verlieren.\n\nReist nach Revendreth und unterstützt sie. Ihr müsst ihnen beweisen, dass wir sie nicht im Stich lassen und dass wir gemeinsam stärker sind.", sourceObjective = "Schließt 3 Weltquests in Revendreth ab.", completion = "Während wir unseren Verbündeten helfen, erinnern wir uns alle an die Bande, die uns in unserer Welt zusammenhalten. Gemeinsam werden wir alles überwinden, und nur, wenn wir zusammenhalten, werden die Schattenlande wieder funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[60383] = { id = 60383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Maldraxxus", description = "Maldraxxus verteidigt uns gegen die Streitkräfte, die die Schattenlande bedrohen, oder wenigstens hat es das einst getan.\n\nJetzt wird es von inneren Kämpfen und einem Ungleichgewicht der Macht geplagt.\n\nWir haben nur wenige Verbündete dort, aber die wenigen, die uns bleiben, müssen wir erhalten.\n\nGeht dorthin, unterstützt sie und helft ihnen dabei, ihre Häuser wieder zu vereinen, sodass die Armeen der Unvergänglichen uns erneut verteidigen können.\n\nOhne sie muss uns nur noch eine Invasion heimsuchen, um uns vollkommen auszulöschen.", sourceObjective = "Schließt 3 Weltquests in Maldraxxus ab.", completion = "Jetzt sind wir der Neuformierung der Armee, die unsere Welten verteidigen wird, einen Schritt nähergekommen. Ihr habt heute Gutes bewirkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60384] = { id = 60384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Bastion", description = "Die Einwohner der Bastion dienen den Schattenlanden schon sehr lange, mit Ehre und unerschütterlichem Glauben. Ohne sie hätten wir keine Seelen, die wir nähren können, und unser Land würde welken und sterben.\n\nWir dürfen nicht zulassen, dass die Bastion fällt, denn ohne sie sind wir verloren.\n\nZieht mit gezückter Waffe in die goldenen Felder und steht unseren belagerten Verbündeten zur Seite. Zeigt ihnen, dass sie in diesen dunklen Zeiten nicht allein sind.", sourceObjective = "Schließt 3 Weltquests in der Bastion ab.", completion = "Auch in dunklen Zeiten dürfen wir andere mit ihrem Kummer nicht allein lassen. Nur wenn wir alle zusammenstehen, werden die Schattenlande ihre alte Stärke wiederfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60385] = { id = 60385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung in Revendreth", description = "Die von dem Verräter Denathrius beherrschten, dunklen Lande von Revendreth stellen ein großes Risiko für uns dar, bieten uns aber gleichzeitig eine gute Gelegenheit zum Üben.\n\nKommt her, Schüler! Heute jagt Ihr mit <dem Schlundgänger/der Schlundgängerin>. Solltet Ihr zu mir zurückkehren, werden wir das mit einer Jagd feiern.\n\nDenn morgen gehen wir auf die Jagd.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in Revendreth ab.", completion = "Ich wittere eine Gruppe erfolgreicher Jäger, gut. Jede erfolgreiche Jagd ist ein weiterer Schritt auf dem Weg zu einem ausgebildeten Jagdrudel.", sourceObjectiveStatus = "unverified-source-field" }
quests[60386] = { id = 60386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung in Maldraxxus", description = "Die Ausbildung und Führung der Streitkräfte von Maldraxxus gehören zu den besten der Schattenlande. Einst haben sie uns verteidigt, jetzt müssen wir uns allein durchschlagen.\n\nEs gibt nur wenige Orte, an denen unsere Schüler besser Erfahrungen im Kampf und in der Strategie sammeln können, als auf ihren blutgetränkten Schlachtfeldern.\n\nNehmt diesen Schüler heute mit auf Eure Reisen, um Kampferfahrung aus erster Hand zu sammeln.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in Maldraxxus ab.", completion = "Kaum etwas ist besser als echte Kampferfahrung, um die nächste Generation unserer Jäger auszubilden. Danke, dass Ihr diesen Schüler am Leben gehalten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60387] = { id = 60387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung in der Bastion", description = "Unsere Jäger haben keine Zeit für eine lange Ausbildung. Also müssen sich Schüler in echten Einsätzen beweisen.\n\nUnsere Verbündeten in der Bastion benötigen dringend Unterstützung und ich möchte, dass Euch bei dieser Aufgabe einer der Neulinge begleitet.\n\nHabt Ihr verstanden, Frischling? Heute begleitet Ihr <den Schlundgänger/die Schlundgängerin>!\n\nUnd seid nicht zu nachsichtig, <Schlundgänger/Schlundgängerin>.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in der Bastion ab.", completion = "Gut. Ein müder Schüler ist ein Schüler mit Kampferfahrung. Das habt Ihr gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60388] = { id = 60388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung für unsere Truppen", description = "Aufstehen, Schüler, Ihr müsst aufstehen!\n\nSeht her! Dieser braucht noch viel Übung, bevor wir eine Chance gegen unsere Feinde haben werden.\n\nWir haben heutzutage nur verschwindend wenig Zeit, um Kampferfahrung aufzubauen, weil uns zu viele Feinde auf den Fersen sind.\n\nNehmt diesen Schüler heute mit, zeigt ihm, wie man kämpft, und beschützt ihn vor allen Widrigkeiten. Sonst werden wir nicht genug Fortschritte erzielen.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests im Ardenwald ab.", completion = "Ihr habt gute Arbeit geleistet. Wir werden ihm gestatten, sich eine Weile auszuruhen. Heute hat er gelernt, dass auch auf der friedlichsten Aue immer Gefahren lauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[60389] = { id = 60389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Ardenwald", description = "Hallöchen, habt Ihr einen Moment?\n\nIst eine Menge los hier im Ardenwald. Üble Sachen, Käfer und sowas. Sehen lecker aus, werden mir aber wohl eher den Magen umdrehen.\n\nWir stehen heute ziemlich gut da, seht Ihr? Die da unten könnten wahrscheinlich Hilfe gebrauchen. Vielleicht helfen sie uns dann als Gegenleistung, versteht Ihr?\n\nMuss ich es Euch aufschreiben? Macht, dass Ihr hinkommt, Trottelchen.", sourceObjective = "Schließt 3 Weltquests im Ardenwald ab.", completion = "War noch nie ein Freund der Nachtfae, aber vielleicht wird es Zeit, dass wir uns nach mehr Verbündeten umschauen. Man muss ja irgendwo anfangen, schätze ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[60390] = { id = 60390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Ardenwald", description = "Unsere Feinde greifen uns von allen Seiten an, <Schlundgänger/Schlundgängerin>.\n\nUnd der Ardenwald sieht sich einer ähnlichen Bedrohung gegenüber.\n\nEs ist in unserem besten strategischen Interesse, stabile Bündnisse außerhalb von Maldraxxus zu schmieden. Wir mögen zwar angegriffen werden, aber wir sind immer noch die stärkste Militärmacht in den Schattenlanden. Unter unserem Schutz werden sie erblühen und uns als Gegenleistung Hilfe zukommen lassen, wenn wir sie benötigen.\n\nGemeinsam sind wir stark. Dies ist die Lehre der Phalanx und es wird auch unsere sein.", sourceObjective = "Schließt 3 Weltquests im Ardenwald ab.", completion = "Stabilität im Ardenwald wird uns von Nutzen sein, wenn wir den Feind angreifen. Eine solide strategische Wahl, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[60391] = { id = 60391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Ardenwald", description = "Der Ardenwald ist seit Langem einer unserer engsten Verbündeten bei Hut und Pflege der Seelen. Und jetzt werden seine Bewohner von allerlei Feinden angegriffen. Wir lassen nicht zu, dass sie fallen!\n\nReist so schnell wie möglich in ihr bewaldetes Land und erweist mit dem Segen der Archon den wohl größten aller Dienste. Steht ihnen in der Stunde ihrer Not zur Seite, als ihr güldener Schild und als Versprechen, dass sie niemals allein sind.\n\nDie Bastion hält zu ihnen, und mit uns werden sie niemals untergehen!", sourceObjective = "Schließt 3 Weltquests im Ardenwald ab.", completion = "Uns wird heute der Segen zuteil, dass der Schlundgänger unsere heilige Pflicht im Ardenwald erfüllt hat! Unsere Verbündeten bejubeln Eure Siege!", sourceObjectiveStatus = "unverified-source-field" }
quests[60392] = { id = 60392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Bastion", description = "In unseren goldenen Hügeln geht das Böse um. Wir lassen nicht zu, dass es hier Wurzeln schlägt und sich noch weiter ausbreitet!\n\nErhebt Eure Stimme, <Schlundgänger/Schlundgängerin>, und schreit es allen Feinden der Bastion entgegen! Wir kommen und wir werden sie vernichten!\n\nUnd jetzt eilt und leiht Eure Macht allen, die ihrer Hilfe bedürfen. Fegt mit scharfer Glaubensklinge Zweifel und Ungewissheit beiseite. Zerschmettert mit güldener Faust die Verzweiflung und zeigt ihr die furchtbare Rache der Archon!\n\nFür die Bastion!", sourceObjective = "Schließt 3 Weltquests in der Bastion ab.", completion = "Die Hügel singen von Eurer Ehre und Eurem unerschütterlichen Glauben. Jeder Sieg gibt unseren Truppen neuen Mut! Ehre sei der Bastion, Ehre sei der Archon und Ehre sei dem Schlundgänger!", sourceObjectiveStatus = "unverified-source-field" }
quests[60393] = { id = 60393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Bastion", description = "Die Kyrianer der Bastion spielen eine einzigartige Rolle in den Schattenlanden und ohne sie können wir unsere Streitkräfte nicht aufstocken. Wenn wir in Maldraxxus siegreich sein wollen, müssen wir sie jetzt mit einem Teil unserer Stärke unterstützen.\n\nGeht zur Bastion und helft, wo Ihr könnt, damit sich die Lage stabilisiert. So sichert Ihr gleichzeitig die Zukunft unserer Armeen und schneidet den Feind von seinem Nachschub ab.\n\nViele Kriege werden nicht auf dem Schlachtfeld entschieden, sondern durch den Nachschub.", sourceObjective = "Schließt 3 Weltquests in der Bastion ab.", completion = "Wir sind unserem Ziel einer stetigen Versorgung mit Seelen jetzt schon einen Schritt näher, Schlundgänger. Damit ist ein entscheidender Vorteil im Krieg um Maldraxxus gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60394] = { id = 60394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Bastion", description = "Wenn die Kyrianer aus der Bastion keine Seelen in die Schattenlande schaffen, bekommen wir keine neuen Kumpels ran. Und keine Anima aus den Sündensteinen mehr. Echt übel, wenn's nicht bald besser wird. Heute und auch in Zukunft.\n\nWir haben hier für den Moment alles unter Kontrolle. Macht Ihr Euch auf zu den gold'nen Hügeln der Bastion und greift ihnen mal unter die Arme. Wette, die revanchieren sich irgendwann. Die haben's ja so mit Ehre und all dem Zeug.\n\n<Rendel zieht laut die Nase hoch.>", sourceObjective = "Schließt 3 Weltquests in der Bastion ab.", completion = "Wollte immer schon mal 'nen Provost verspeisen. Hat sich irgendwie nie ergeben. Wie die wohl schmecken?\n\nNa ja, war auf jeden Fall gut, was Ihr da für sie getan habt. Aber ein paar Dinge gehen mir halt nie aus dem Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[60395] = { id = 60395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Maldraxxus", description = "Auch in den fauligen Ödlanden von Maldraxxus finden sich unsere Verbündeten. Nicht alle haben ihre heilige Pflicht als Hüter der Schattenlande vergessen.\n\nWir müssen uns beeilen und unseren knöchernen Brüdern zur Seite stehen. Schulter an Schulter, Hand in Hand werden wir allen trotzen, die Chaos und Zwietracht säen.\n\nEin Speer aus Gold und Knochen werden wir sein! Und tief in sein Herz wird dieser Speer das Böse treffen!\n\nUnd jetzt geht, <Schlundgänger/Schlundgängerin>. Ihr seid die Speerspitze in dieser glorreichen Schlacht!", sourceObjective = "Schließt 3 Weltquests in Maldraxxus ab.", completion = "Glorreich! Die güldenen Gemäuer der Bastion stehen unseren Verbündeten in Maldraxxus treu zur Seite. Möge sie der Mut im Kampf für Gerechtigkeit nie verlassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[60396] = { id = 60396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Maldraxxus", description = "Wir mögen nur wenige Verbündete in Maldraxxus haben, aber wir können sie nicht im Stich lassen. Jede Hand, die wir aus der Dunkelheit zu uns führen, kann eine Waffe oder einen Zauberstab halten.\n\nDurchstreift unser Land, findet die Hilfsbedürftigen und helft ihnen. Zermalmt unsere Feinde und zeigt ihnen, dass wir überall sind. Lehrt sie, Euch zu fürchten.\n\nFurcht sät Zweifel, und Zweifel ist die Wurzel, die Königreiche umstürzt.", sourceObjective = "Schließt 3 Weltquests in Maldraxxus ab.", completion = "Unsere konkurrierenden Häuser werden zweimal darüber nachdenken, bevor sie einen Fuß aus ihren Hochburgen setzen. Blut und Ruhm für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[60397] = { id = 60397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Maldraxxus", description = "Es gab mal 'ne Zeit, in der diese Gerippe in Maldraxxus uns alle hier in den Schattenlanden verteidigt haben. Jetzt verbringen sie ihre Zeit damit, das Wenige zu zerstören, was noch übrig ist.\n\nIch weiß nur, wenn's so weitergeht, könnte ein gewaltiger Schwarm Verschlinger über uns hereinbrechen und uns alle auslöschen.\n\nGeht da hin und helft den Guten, den Frieden zu wahren, vielleicht helfen sie uns auch mal.", sourceObjective = "Schließt 3 Weltquests in Maldraxxus ab.", completion = "Vielleicht stabilisieren sich die Dinge da unten in Maldraxxus jetzt wieder. Würd uns allen guttun.", sourceObjectiveStatus = "unverified-source-field" }
quests[60398] = { id = 60398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Revendreth", description = "Unsere Verbündeten in Revendreth sind das Einzige, was die Flut von Denathrius' Streitkräften davon abhält, den Rest der Schattenlande zu übernehmen.\n\nEinst hätte man uns damit betraut, diesem Unrecht entgegenzutreten, aber unsere Armeen sind durch die Taten unserer rivalisierenden Häuser geschrumpft.\n\nHeute werdet Ihr der Bote von Maldraxxus sein und eine Botschaft der Gerechtigkeit im Namen des großen Kreislaufs überbringen, dem wir alle angehören.\n\nEs ist Eure vom Primus gegebene Pflicht, Sündensturz gegen die zu unterstützen, die diesen Kreislauf durchbrechen wollen.", sourceObjective = "Schließt 3 Weltquests in Revendreth ab.", completion = "Mit Eurer Hilfe konnten wir endlich wieder unseren heiligen Pflichten bei der Verteidigung der Schattenlande nachkommen. Schritt für Schritt machen wir die Fehler wieder gut, die uns in die Irre geführt haben. Dann kann der Zyklus wieder von Neuem beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60399] = { id = 60399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Revendreth", description = "Ey, Ihr da, ich hab heute was zu tun für Euch.\n\nViele Probleme außerhalb von Sündensturz. Große Probleme, kleine Probleme, alle möglichen Probleme.\n\nGegen Denathrius können wir nich' viel ausrichten, wenn dieser Haufen uns ständig an den Fersen klebt, nich'?\n\nGeht da raus und macht Euch die Stiefel dreckig.", sourceObjective = "Schließt 3 Weltquests in Revendreth ab.", completion = "Ihr habt heute was Gutes getan, und deshalb sind wir jetzt sicherer. Ich werfe ja sonst nich' mit Komplimenten um mich, aber Ihr habt Euch echt gut geschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60400] = { id = 60400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Revendreth", description = "Eilt nach Revendreth, wo Graf Denathrius die loyalen Diener der Schattenlande mit eiserner Faust zu brechen sucht.\n\nWir dürfen nicht zulassen, dass sie fallen. Ohne die Hilfe von Sündensturz lassen sich die Streitkräfte von Revendreth nicht im Zaum halten und ihre dunkle Allianz mit dem Kerkermeister könnte uns alle vernichten.\n\nWir von der Bastion werden das niemals zulassen! Erhebt Eure Schwerter, haltet Eure Schilde bereit und tragt den glorreichen Mut der Bastion nach Revendreth!", sourceObjective = "Schließt 3 Weltquests in Revendreth ab.", completion = "Auch fern unseres Landes finden wir Verbündete in diesen dunklen Zeiten. Selbst wenn das Böse unsere Schwingen bricht, dienen wir! Mit Ehre und Glauben! Für sie und für die gesamten Schattenlande!", sourceObjectiveStatus = "unverified-source-field" }
quests[60401] = { id = 60401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung im Ardenwald", description = "Ich habe noch einen Lehrling für Euch, der Ausbildung auf dem Schlachtfeld benötigt. Geht mit ihm, ach, ich weiß nicht, in den Ardenwald.\n\n<Sakaa deutet vage in die Richtung des Ardenwalds.>\n\nDa drüben gibt es vieles, was man verstümmeln kann und vielleicht lernt er auch noch das eine oder andere über Holz.\n\n<Sakaa schmunzelt.>", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests im Ardenwald ab.", completion = "Oh, nun, gute Arbeit, dass Ihr ihn mitgeschleift habt. Hoffentlich hat er Euch keinen Ärger bereitet.\n\nNa ja, vielleicht wäre ein bisschen Ärger akzeptabel.", sourceObjectiveStatus = "unverified-source-field" }
quests[60402] = { id = 60402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung im Ardenwald", description = "Seht sie euch an! Knochen und Knorpel, der ganze Haufen. Brauchen Fleisch auf den Knochen und Ausbildung im Kopf.\n\nNehmt diesen Schüler mit und verschafft ihm echte Kampferfahrung.\n\nDer Ardenwald ist dafür ein guter Ort, da kann man gegen alles Mögliche kämpfen. Neue Strategien lernen, sich an das Chaos einer Schlacht gewöhnen, all sowas.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests im Ardenwald ab.", completion = "Gut, gut, ich sehe schon, der hier hat heute das eine oder andere gelernt. Ab hier übernehme ich wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[60403] = { id = 60403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung im Ardenwald", description = "Es ist unsere große Pflicht, aufstrebende Krieger im Kampf auszubilden.\n\nDas ist Euer Schützling für heute. Besucht den Ardenwald und zeigt Eurem Schüler, was es bedeutet, im glorreichen Dienste der Archon zu stehen. Beschützt unsere Verbündeten und tragt neue Zuversicht in ihr Land.\n\nZeigt ihnen, was wahre Kampfkunst und wahre Ehre sind.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests im Ardenwald ab.", completion = "Ihr seid mit Euren Leuten wohlbehalten zurückgekehrt, wie gütig. Tragt die Lektionen des Lehrers mit Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[60404] = { id = 60404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung für unsere Truppen", description = "Gibt es einen besseren Ort, um unsere Schwingen zu strecken, als unsere eigenen Felder?\n\nNehmt heute einen unserer Schüler mit und zeigt allen in der Bastion, wie man richtig kämpft. Die Lage hier wird mit jedem Tag ernster.\n\nEin wichtiger Teil dieser Ausbildung ist, gegen die zu Felde zu ziehen, die sie einst Brüder und Schwestern nannten.\n\nSo manches Herz und manchen Willen hat diese Prüfung bereits gebrochen.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in der Bastion ab.", completion = "Euer Schützling hat etwas Ruhe verdient. Der Kampf gegen Bedrohungen von innen, besonders gegen jene, die einst als Brüder und Schwestern galten, ist eine schwere Bürde.", sourceObjectiveStatus = "unverified-source-field" }
quests[60405] = { id = 60405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung in der Bastion", description = "Nutzlose Schergen, einer wie der andere. Dieses ganze Frontfutter brauch mal eine richtige Lektion.\n\nHier, nehmt diesen nutzlosen Neuling mit. Und dann weit weg mit ihm. Geht... zur Bastion. Ja, zur Bastion. Weit, weit weg von mir.\n\nDa gibt's jede Menge zu lernen.\n\nUnd wenn der Neuling das nicht überlebt, will ich nichts davon hören.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in der Bastion ab.", completion = "So, so. Ihr seid also beide wieder da. Und an einem Stück. Bin überrascht. Vielleicht seid Ihr ja ein besserer Lehrmeister, als ich gedacht hatte. Werde ich mir merken.", sourceObjectiveStatus = "unverified-source-field" }
quests[60406] = { id = 60406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung in der Bastion", description = "Ich habe noch einen weiteren Diener, ähm, Rekruten, der ausgebildet werden muss.\n\nNehmt ihn mit auf die fruchtbaren Felder der Bastion. Dort kann er viel Neues über Dinge lernen, die in dieser Gegend nicht zu finden sind. Vielleicht wächst er dadurch zu einem besseren Soldaten heran.\n\nWomöglich lernt auch Ihr ein paar neue Tricks, während Ihr dort draußen seid.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in der Bastion ab.", completion = "Danke, dass Ihr den Neuen helft. Aber sie haben trotzdem noch viel zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60407] = { id = 60407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung in Maldraxxus", description = "Unsere aufstrebenden Krieger müssen im Feuer der Schlacht geschmiedet werden. Unter den härtesten Bedingungen. Der Krieg ist kein Spiel und gönnt ihnen keine Atempause.\n\nGeht mit diesem Neuling nach Maldraxxus, ins Zentrum der militärischen Macht der Schattenlande. Das ganze Land droht in Chaos und Aufruhr zu versinken. Überall lauern gefallene Champions und Gladiatoren.\n\nDort wird Euer Schüler sich echten Herausforderungen stellen und Dinge lernen, die ihm niemand beibringen kann.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in Maldraxxus ab.", completion = "Ah, Euer Schützling ist noch an einem Stück. Sehr gut. Ganz unter uns: Wenn wir Schüler auf solch eine Mission schicken, ist das immer ein großes Risiko. Gut, dass Ihr dabei wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[60408] = { id = 60408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung für unsere Truppen", description = "Unsere Armeen sind nichts ohne Kampftraining, aber jedes Mal, wenn wir sie aussenden, kommen sie als Haufen Fleisch und Knochen zurück.\n\nWählt einen Lehrling aus und lasst ihn gegen die Streitkräfte der anderen Häuser antreten. Aber er soll nicht getötet werden, ja? Nicht ganz. Ein bisschen ist genug.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in Maldraxxus ab.", progress = "Glück gehabt?", completion = "Bei meinen Knochen, Ihr seid zurück und Euer Lehrling ist kein Matsch. Ich kann meinen Augenhöhlen kaum trauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60409] = { id = 60409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung in Maldraxxus", description = "Es gibt noch einen Lehrling, der betreut werden muss, wenn es Euch nichts ausmacht.\n\nIn Maldraxxus wird ständig gekämpft, deshalb geht man wohl am besten mit ihm dorthin. Er muss etwas über Krieg und Strategie und all das lernen.\n\nEinfach in die Arena werfen oder so. Friss oder stirb ist eine effektive Trainingsmethode.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in Maldraxxus ab.", completion = "Euer Lehrling sieht ein wenig zerrupft aus, aber trotz allem unbeschadet. Hat wahrscheinlich das ein oder andere gelernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60410] = { id = 60410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung für unsere Truppen", description = "Ich hab ein paar neue Truppen für Euch, die Ihr ausbilden könnt. Gibt viel zu tun hier in unserem Reich. \n\nNehmt sie mit nach draußen und gebt ihnen einen ordentlichen und vermutlich blutigen Vorgeschmack auf das, womit wir es zu tun haben.\n\nUnd wenn es sie umbringt? Dann geht es mich nichts an.\n\n<Sakaa nippt an einem dickflüssigen und süßlich riechenden Getränk.>", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in Revendreth ab.", completion = "Sieht aus, als ob Ihr dem hier heute ein paar gute Erfahrungen eingebläut hättet. Nur ein paar gebrochene Knochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[60411] = { id = 60411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung in Revendreth", description = "Lausige, nutzlose Knochenansammlung. Diese Armee ist weniger eine Armee als ein Haufen herumlaufendes, totes Fleisch.\n\nTut mir einen Gefallen, nehmt diesen Schüler und geht mit ihm nach Revendreth. Bildet ihn gut im Kampf gegen einige unserer Gegner aus, gebt ihm eine kleine Kostprobe von Strategie und Taktik und davon, was es heißt, wenn einem Magie ins Gesicht schlägt.\n\nSie alle werden uns nichts nützen, wenn wir ihnen keine Ausbildung zukommen lassen können, die nicht in einem Haufen toter Diener endet.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in Revendreth ab.", progress = "Und? Bringt Ihr einen Haufen Knochen oder einen Schüler zurück?", completion = "Na, der scheint ja jetzt etwas mehr im Kopf zu haben. Vielleicht überlebt er jetzt eine Schlacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60412] = { id = 60412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung in Revendreth", description = "Ein Schüler braucht Eure starke Führung.\n\nGeht gemeinsam nach Revendreth. Dort lauern die Armeen von Denathrius auf eine Chance, uns alle zu vernichten. Stellt Euch gemeinsam diesem mächtigen Feind.\n\nErringt einen glorreichen Sieg und kehrt als Schild und <stolzer Mentor/stolze Mentorin> zurück, auf dass unsere Armee in Zukunft noch stärker wird.", sourceObjective = "Schließt mit Eurem Lehrling 3 Weltquests in Revendreth ab.", completion = "Ein weiterer glorreicher Tag der Ausbildung im Namen der Archon! Euer Neuling darf sich nun erst einmal ausruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60414] = { id = 60414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Ressourcen", description = "Die Mittler sind merkwürdige Persönlichkeiten, aber nützlich. Sie können im Gegensatz zu uns viele Dinge in den weitläufigen Reichen der Schattenlande finden.\n\nWir haben uns seit vielen Jahren darauf verlassen, dass sie uns nützliche Materialien bringen, aber heutzutage haben wir nur wenig zum Handeln.\n\nSie bevorzugen im Allgemeinen ihre eigene Währung, die Mittlermünzen.\n\nWenn Ihr diese auf Euren Reisen findet, wäre ich Euch für eine Handvoll von ihnen sehr dankbar, da ich dafür einige seltene und notwendige Gegenstände erwerben kann.", sourceObjective = "Sammelt 3 Mittlermünzen von seltenen Monstern und Schatztruhen in den Schattenlanden.", progress = "Habt Ihr Münzen gefunden?", completion = "Oh, da habt Ihr ja einiges zusammengetragen. Damit werde ich einige äußerst seltene Zutaten und Materialien erwerben können, und damit können wir vielleicht das Blatt gegen unsere Feinde wenden. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60415] = { id = 60415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Ressourcen", description = "Hallo! Ja! Hallo.\n\nMittler. Ihr kennt Mittler?\n\n<Sika gibt ihr Bestes, einen Mittler zu imitieren. Mit eher mäßigem Erfolg.>\n\nTauschen viele Dinge mit uns. Was uns fehlt. Was wir wollen.\n\nAber nur mit Münzen. Klimper, klimper!\n\n<Sika formt mit ihren Handfedern einen Kreis.>\n\nFinden sich überall. Bringt sie zu Sika!", sourceObjective = "Sammelt 3 Mittlermünzen von seltenen Monstern und Schatztruhen in den Schattenlanden.", progress = "Bringt Münzen zu Sika? Für Handel mit Mittlern. Ihr wisst doch?", completion = "Münzen! Münzen für Sika! Sika glücklich, Freunde glücklich. Gut für viele Dinge. Seltsame Dinge. Versteht Ihr nicht. Ist schon gut.\n\n<Sika nimmt die Münzen und winkt Euch zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60416] = { id = 60416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Ressourcen", description = "Kh-kh-kh... Die Mittler kommen an viele Orte. Viele Orte, an die wir nicht können. Die Augen können ihnen nicht folgen.\n\nSie finden viele Geheimnisse, ja. Bringen uns Vorräte, seltsam und selten.\n\nBrauche Dinge zum Handeln. Brauche Mittlermünzen.\n\nSie handeln mit allen. Finden Münzen in jedem Land. Tötet die, die sie haben, bringt mir die Münzen. \n\nIhr könnt Ihre Leichen fressen, ich urteile nicht. Brauche nur Münzen.", sourceObjective = "Sammelt 3 Mittlermünzen von seltenen Monstern und Schatztruhen in den Schattenlanden.", progress = "Bringt mir Münzen? Münzen für Mittler. Vielseitig. Seht Ihr?", completion = "Das Klimpern der Münzen ist der Klang aufgedeckter Geheimnisse. Vielseitig, viele Dinge, die ich kaufen werde. Wir werden mächtiger deswegen. Ein guter Fund.", sourceObjectiveStatus = "unverified-source-field" }
quests[60417] = { id = 60417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Ressourcen", description = "Die Mittler sind eine rätselhafte Gruppe. Wir wissen wenig über sie, nur, dass sie in viele Länder der Schattenlande reisen können, zu denen wir keinen Zugang haben. Wie sie das machen, wissen wir nicht genau.\n\nSie sind jedoch willige Handelspartner und durch sie haben wir viele seltene und wertvolle Ressourcen erworben, die anderswo nicht zu finden sind.\n\nSie schätzen eine von Ihnen selbsterschaffene Währung sehr. Vielleicht findet Ihr solche Münzen auf Euren Reisen.\n\nIch nehme sie Euch gerne ab, um unsere Vorräte aufzustocken.", sourceObjective = "Sammelt 3 Mittlermünzen von seltenen Monstern und Schatztruhen in den Schattenlanden.", progress = "Habt Ihr ein paar Mittlermünzen gefunden?", completion = "Mit dieser kleinen Handvoll Münzen können wir viele nützliche Dinge kaufen. Ich werde mich sofort mit ihnen in Verbindung setzen.\n\nIch danke Euch, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[60418] = { id = 60418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zur Bastion", description = "Unsere Verbündeten in der Bastion sind unverzichtbar für die Funktion der Schattenlande. Sie allein können uns all die Seelen bringen, die wir brauchen, damit der Kreislauf nicht versiegt.\n\nSollten sie der Dunkelheit erliegen, ist es nur eine Frage der Zeit, bis auch wir welken und sterben.\n\nUnd im Augenblick trifft sie eine Katastrophe nach der anderen. Wir müssen dorthin und ihnen helfen!", sourceObjective = "Verteidigt die Bastion, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Spitzen des Aufstiegs\" und \"Die Nekrotische Schneise\" besiegen.", completion = "Unsere kyrianischen Verbündeten melden, dass Ihr ihnen einen gewaltigen Dienst erwiesen habt! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[60419] = { id = 60419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Heimatfront", description = "Es heißt ja, die gesamten Schattenlande wären eine Bühne, und gerade jetzt habe ich das Gefühl, wir stecken mitten in einer Tragödie!\n\nIm gesamten Ardenwald greifen sie uns an. Sie haben es auf unsere Anima und die Seelen abgesehen, die wir beschützen.\n\nWenn der Kreislauf hier endet, sind so viel große Seelen verloren... auf ewig.\n\nWir dürfen keine Zeit verlieren. Ihr müsst uns helfen! Verteidigt den Ardenwald!", sourceObjective = "Verteidigt den Ardenwald, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Nebel von Tirna Scithe\" und \"Die Andre Seite\" besiegen.", completion = "Ich habe viel über Eure großen Taten gehört. Die Winterkönigin ist sehr zufrieden!\n\nHier, das ist für Euch. Kämpft weiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[60420] = { id = 60420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf nach Maldraxxus", description = "Gut, dass Ihr hier seid. Wir haben einige Probleme in Maldraxxus.\n\nDie Streitkräfte von Maldraxxus sind die Beschützer der Schattenlande. Bisher haben die Häuser sich immer die Waage gehalten wie Schauspieler auf einer Bühne. Keines hat sich zu sehr ins Rampenlicht gedrängt, um es den anderen zu stehlen.\n\nAber jetzt haben einige das Gleichgewicht gestört und wollen den Rest von uns unterjochen!\n\nUnsere Verbündeten dort brauchen dringend Hilfe! Helft ihnen, wo immer Ihr könnt.", sourceObjective = "Verteidigt Maldraxxus, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons Seuchensturz und Theater der Schmerzen besiegen.", progress = "Hat sich die Lage in Maldraxxus schon verbessert?", completion = "Die Häuser von Maldraxxus sind wieder im Gleichgewicht und keine Bedrohung mehr... zumindest für die nächste Zeit.\n\nDas habt Ihr gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[60421] = { id = 60421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf nach Revendreth", description = "Oh, bin ich froh, dass Ihr da seid. Wir haben ein Problem!\n\nUnsere Freunde in Revendreth leiden schwer unter der Herrschaft von Graf Denathrius. Er war schon immer ein grausamer Herrscher, aber jetzt hat er sich mit dem Kerkermeister verbündet!\n\nWenn wir Revendreth nicht aus dem Würgegriff von Denathrius befreien, sind wir sein nächstes Ziel...\n\nWir müssen alles tun, um ihnen zu helfen!", sourceObjective = "Verteidigt Revendreth, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Die Blutigen Tiefen\" und \"Hallen der Sühne\" besiegen.", completion = "Ha, nehmt das, Denathrius. Solange Ihr noch ein Wörtchen mitzureden habt, wird er die Schattenlande niemals beherrschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[60422] = { id = 60422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zum Ardenwald", description = "Allein sind wir verloren. Wenn nur ein Teil der Schattenlande fällt, sind wir alle in Gefahr.\n\nDie großen Seelenbäume im Ardenwald werden von vielen Feinden angegriffen, die sich ihre Macht zunutze machen wollen.\n\nWir müssen unseren Verbündeten bei den Nachtfae helfen und diese Eindringlinge für ihren Frevel bestrafen.\n\nGemeinsam sind wir stärker.", sourceObjective = "Verteidigt den Ardenwald, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Nebel von Tirna Scithe\" und \"Die Andre Seite\" besiegen.", completion = "Ihr habt unsere Allianz mit den Nachtfae gesichert und somit unsere Position in den ganzen Schattenlanden gestärkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60423] = { id = 60423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zum Ardenwald", description = "Der Ardenwald war einst an Ort des Friedens und der Erneuerung, aber jetzt ist er von dunklen Mächten umzingelt.\n\nEs ist allein die Aufgabe von Maldraxxus, alle zur Rechenschaft zu ziehen, die den Zyklus stören.\n\nNehmt unsere Banner, erhebt Eure Waffen und bringt den Krieg in den Ardenwald.\n\nFür die Schattenlande.", sourceObjective = "Verteidigt den Ardenwald, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Nebel von Tirna Scithe\" und \"Die Andre Seite\" besiegen.", completion = "Der Zyklus geht weiter, so ist unser Wille.\n\nMit jedem Feind, der durch Eure Hand fällt, mehrt Ihr den Ruhm und die Bedeutung von Maldraxxus.", sourceObjectiveStatus = "unverified-source-field" }
quests[60424] = { id = 60424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zum Ardenwald", description = "Der Ardenwald ist einer unserer treuesten Verbündeten und erhält von uns einige der stärksten Seelen.\n\nSollte der Wald fallen, könnte das eine Welle der Zerstörung auslösen, die uns alle vernichtet.\n\nWir müssen der Winterkönigin helfen. So lautet der Wille der Archon.\n\nGeht jetzt und helft den Nachtfae.", sourceObjective = "Verteidigt den Ardenwald, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Nebel von Tirna Scithe\" und \"Die Andre Seite\" besiegen.", completion = "Unsere Verbündeten im Ardenwald singen das höchste Lob auf Eure großen Taten. Wieder einmal habt Ihr bewiesen, dass die Kyrianer für die Schattenlande und unsere Verbündeten kämpfen. Was es uns auch kosten mag.\n\nMögen Mut und Weisheit Euch nie verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60425] = { id = 60425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Heimatfront", description = "Manchmal müssen wir nach innen blicken, um wahre Dunkelheit zu finden. Hier in der Bastion, wo einst Harmonie herrschte, wimmelt es nun von Feinden.\n\nHeute werden wir sie mit Stumpf und Stiel ausrotten.\n\nZieht mit gezückter Waffe in die goldenen Felder. Befreit uns von diesen abscheulichen Kreaturen und helft unseren Truppen, wo Ihr könnt.\n\nIm Namen der Archon.", sourceObjective = "Verteidigt die Bastion, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Spitzen des Aufstiegs\" und \"Die Nekrotische Schneise\" besiegen.", completion = "Die Glocken läuten in der Ferne und künden von Eurer Rückkehr. Ein glorreicher Klang.\n\nIhr habt uns heute einen großen Dienst erwiesen und Euch wahrlich einen Platz in unseren Reihen gesichert.\n\nEhre sei mit Euch, glorreicher Sieger!", sourceObjectiveStatus = "unverified-source-field" }
quests[60426] = { id = 60426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zur Bastion", description = "Wir, die Verteidiger der Schattenlande, schrecken vor keinem Feind zurück. Und mag er noch so mächtig sein.\n\nLange haben die Kyrianer der Bastion die Seelen weitergeleitet und so den ganzen Schattenlanden einen großen Dienst erwiesen. Ohne sie wären wir alle verloren.\n\nUnd jetzt hat der Feind auch in ihre Reihen Einzug gehalten. Wir müssen sie in der Stunde ihrer Not beschützen.\n\nGeht im Namen des Primus und kehrt ehrenvoll zurück.", sourceObjective = "Verteidigt die Bastion, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Spitzen des Aufstiegs\" und \"Die Nekrotische Schneise\" besiegen.", completion = "Wir werden die Schattenlande immer beschützen, auch wenn der Feind in unseren Reihen lauert.\n\nIhr habt gezeigt, dass sich niemand vor dem starken Arm von Maldraxxus verstecken kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[60427] = { id = 60427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zur Bastion", description = "Die Bastion ist für den Kreislauf der Macht in den Schattenlanden unerlässlich. Ohne sie können wir unsere Ränge nicht auffüllen, was den Armeen des Kerkermeisters nur in die Hände spielt.\n\nAber auch für die Bastion sind diese Zeiten schwer. Heute müssen wir nach außen blicken und unseren Verbündeten beistehen.\n\nZieht in die goldenen Felder und befreit sie von ihren Feinden.\n\nNur mit unseren Verbündeten haben wir eine Chance gegen Denathrius.", sourceObjective = "Verteidigt die Bastion, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Spitzen des Aufstiegs\" und \"Die Nekrotische Schneise\" besiegen.", completion = "Die Archon hat uns von Euren Taten berichtet und wird uns in den kommenden Schlachten unterstützen. Noch ein paar Siege in dieser Art, dann sind wir auf dem besten Wege, diesen durchbrochenen Zyklus zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60428] = { id = 60428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge des Primus", description = "Das ist alles, was ich brauche. Zeit, sich an die Arbeit zu machen.\n\nIch würde in der Nähe bleiben, wenn ich Ihr wäre. Eine Waffe zu schmieden ist nie einfach, wenn es um die Arbeit des Primus geht.\n\nWenn ich etwas von ihm gelernt habe, dann, das Unerwartete zu erwarten.", sourceObjective = "Helft Knochenschmiedin Heirmir, Eure Runenklinge zu schmieden.", completion = "Der Primus mochte seine Prüfungen schon immer. Diese habt Ihr wohl bestanden. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60429] = { id = 60429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Heimatfront", description = "Seht! Seht Euch um! Überall warten Feinde auf die zermalmende Hand des Sieges.\n\nDas Machtverhältnis ist gestört, und so sind die Verteidiger der Schattenlande geschwächt.\n\nDas einzige Mittel ist mehr Kampf!\n\nFordert die Häuser heraus, die Maldraxxus stören wollten, und macht sie unter Euren Stiefeln gefügig.", sourceObjective = "Verteidigt Maldraxxus, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons Seuchensturz und Theater der Schmerzen besiegen.", progress = "Habt Ihr den Boden mit den Knochen Eurer Feinde übersät?", completion = "Geschichten Eurer Macht hallen durch das Land. Die Knochen der Gefallenen zittern vor Eurem Namen. Schwelgen wir heute in Eurem Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[60430] = { id = 60430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf nach Maldraxxus", description = "Seit Langem beschützt die Streitmacht von Maldraxxus die Schattenlande gegen alle Bedrohungen von außerhalb.\n\nAber jetzt kommt die größte Bedrohung von innen. Das Gleichgewicht der Kräfte zwischen den Häusern ist dahin. Jetzt greifen sie uns und auch viele andere an.\n\nFür all diese Gefahren haben wir eine simple und gerechte Lösung.\n\nReist nach Maldraxxus, vernichtet alle, die den Schattenlanden schaden, und helft Euren Verbündeten, wo Ihr könnt.", sourceObjective = "Verteidigt Maldraxxus, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons Seuchensturz und Theater der Schmerzen besiegen.", completion = "Nachdem die verräterischen Häuser nun auf Knien um Gnade betteln, sind wir dem Frieden einen Schritt näher. Die Archon dankt Euch für Euren Dienst zum Wohl der Schattenlande.", sourceObjectiveStatus = "unverified-source-field" }
quests[60431] = { id = 60431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf nach Maldraxxus", description = "Die Streitkräfte von Maldraxxus sollten einst die Schattenlande gegen Bedrohungen von außen verteidigen. Jetzt sind sie so gut wie zerschlagen.\n\nDie Häuser sind ins Chaos gestürzt und bekämpfen sich gegenseitig. Wir haben dort nur wenige Verbündete, und diejenigen, die sich auf unsere Seite gestellt haben, sind verletzt und geschlagen.\n\nGeht und helft ihnen. Tötet ihre Feinde. Bringt das Gleichgewicht zurück nach Maldraxxus, und wir werden im Gegenzug Hilfe erhalten.", sourceObjective = "Verteidigt Maldraxxus, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons Seuchensturz und Theater der Schmerzen besiegen.", completion = "Die Krieger von Maldraxxus tragen Euren Namen auf ihren Lippen, damit habt Ihr heute einen großen Sieg errungen. Das Gleichgewicht der Kräfte wird eines Tages wiederhergestellt sein und unsere Bündnisse werden sich auszahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60432] = { id = 60432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Heimatfront", description = "Es gibt viele Aufgaben, die Eure Aufmerksamkeit außerhalb der Mauern von Sündensturz erfordern.\n\nUnsere engsten Verbündeten werden von allen Seiten angegriffen und die Streitkräfte von Denathrius sind unerbittlich.\n\nNehmt Eure Waffe und macht Euch bereit. Heute verteidigen wir Revendreth und errichten somit ein weiteres Bollwerk gegen unsere Feinde.\n\nWir werden uns zurückholen, was uns gehört.", sourceObjective = "Verteidigt Revendreth, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Die Blutigen Tiefen\" und \"Hallen der Sühne\" besiegen.", completion = "Durch Eure heutigen Taten ist unsere Lage sicherer geworden. Revendreth wird nicht unter die Herrschaft von Denathrius fallen, nicht, solange wir standhaft bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[60433] = { id = 60433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf nach Revendreth", description = "Wir kämpfen nicht nur für Macht und Ruhm, sondern für das übergeordnete Wohl der Schattenlande. Es ist unsere Berufung, Krieg gegen diejenigen zu führen, die den Strom der Seelen unterbrechen wollen.\n\nEs gibt solch einen Verräter - Graf Denathrius.\n\nBringt die Rache von Maldraxxus über die widerwärtige Krone auf seinem Haupt.\n\nTötet seine Verbündeten, dient seinen Feinden, lasst seine Herrschaft in einem Blutbad enden.", sourceObjective = "Verteidigt Revendreth, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons Die Blutigen Tiefen und Hallen der Sühne besiegen.", completion = "Denathrius hat nicht erwartet, dass wir so schnell zusammenkommen, um unsere große Vorsehung in diesem Zyklus zu erfüllen.\n\nEr hat unser Haus zum letzten Mal unterschätzt und den Preis mit Blut bezahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60434] = { id = 60434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf nach Revendreth", description = "Wir alle hier dienen dem großen Ganzen, sogar jene in Revendreth, die uns so fremd erscheinen. Wir bringen ihnen die Seelen, die einer harten Läuterung bedürfen, und auch das ist Gerechtigkeit.\n\nAber Graf Denathrius ist zu weit gegangen und strebt nun nach der Alleinherrschaft über die gesamten Schattenlande.\n\nWir haben Freunde unter den Venthyr. Helft ihnen und zermalmt ihre Feinde zu Staub.\n\nDas Wort der Archon ist mit Euch.", sourceObjective = "Verteidigt Revendreth, indem Ihr tägliche Quests und Weltquests abschließt, Schätze erbeutet und seltene Kreaturen tötet. Ihr könnt außerdem mächtige Gegner in den Dungeons \"Die Blutigen Tiefen\" und \"Hallen der Sühne\" besiegen.", completion = "Graf Denathrius darf für seine Verbrechen nicht ungestraft bleiben, und Ihr habt heute ein angemessenes Urteil vollstreckt.\n\n<Polemarch Adrestes verneigt sich in Eure Richtung.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60435] = { id = 60435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in Revendreth", description = "Wir haben Denathrius' Truppen nie wirklich als unsere Verbündeten betrachtet, und nun zeigt er sein wahres Gesicht.\n\nÜber die Jahre hat er eine Armee aufgestellt, die jedes andere Land vernichten könnte. Allerdings nur, wenn wir allein kämpfen anstatt gemeinsam. Er hat monströsen Kreaturen seinen Willen aufgezwungen und ihnen noch mehr Macht geschenkt.\n\nWas gäbe es für einen besseren Weg, unsere Verbündeten zu beschützen und Eure Stärke zu demonstrieren, als seine mächtigsten Champions zu vernichten.\n\nGeht. Die Jagd ist eröffnet.", sourceObjective = "Schließt die Weltquest \"Die Dominanz vernichten\", den Dungeon Die Blutigen Tiefen oder den Dungeon Hallen der Sühne in Revendreth ab.", completion = "Die Generäle unserer Feinde in Revendreth werden es sich zweimal überlegen, bevor sie nach der Macht in den Schattenlanden greifen.\n\nWir haben heute unwahrscheinlichen Verbündeten geholfen und ein aufrichtiges Band mit Revendreth geknüpft. Und das alles verdanken wir Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[60436] = { id = 60436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in Maldraxxus", description = "Maldraxxus ist ein Land voller Konflikte und Zwietracht. Es gibt kaum einen besseren Ort, um Euch gegen die Mächte der Schattenlande zu beweisen.\n\nDort findet Ihr Krieger, die allein für den Kampf leben. Gestählt durch Schwert und Hammer in Arenen und auf dem Schlachtfeld.\n\nZerschmettert sie mit der Wucht eines fallenden Baumes. Zeigt ihnen, dass die Macht des Ardenwalds ebenso furchtbar sein kann wie sie.", sourceObjective = "Schließt die Weltquest \"Auserwählte Champions\", den Dungeon \"Theater der Schmerzen\" oder den Dungeon \"Seuchensturz\" in Maldraxxus ab.", progress = "Wart Ihr siegreich?", completion = "In einem Land der Champions und Kriege habt Ihr Euer Können meisterhaft bewiesen. Nur wenige haben den größten Verteidigern der Schattenlande die Stirn geboten und können heute davon erzählen. Aber hier steht Ihr nun, ein Beweis der Stärke der Nachtfae.\n\nMöge es ewig währen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60437] = { id = 60437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in der Bastion", description = "Die Bastion zählt seit Langem zu unseren engsten Verbündeten und ist für den Zusammenhalt der Schattenlande unerlässlich. Wir können nicht dulden, dass die Reise der Seelen unterbrochen wird.\n\nZwietracht in den eigenen Reihen droht dort in große Unruhe umzuschlagen. Jeden Tag breiten sich Zweifel unter den Truppen aus, nagen an ihrer Hoffnung und stürzen uns tiefer in das Chaos.\n\nZweifel ist ein mächtiger Feind und nicht leicht zu besiegen. Behaltet einen klaren Kopf und löscht diese finsteren Gedanken aus.", sourceObjective = "Schließt die Weltquest \"Treulose Einwohner\", den Dungeon \"Spitzen des Aufstiegs\" oder den Dungeon \"Die Nekrotische Schneise\" in der Bastion ab.", completion = "Ihr habt im Angesicht des Zweifels großen Mut beweisen. Es gibt viele Arten von Stärke, und Ihr habt gezeigt, dass Eure Stärke weiter reicht als nur bis zu Schwert und Bogen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60438] = { id = 60438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen im Ardenwald", description = "Die Wilde Jagd zählt die gefährlichsten Kreaturen des ganzen Waldes zu ihrer Beute. Hier könnt Ihr Euch selbst in Herausforderungen beweisen, wie Ihr sie in Eurem letzten Leben noch nicht gesehen habt.\n\nIm Augenblick bereitet mir die Lage in Tirna Scithe die größten Sorgen. Einst ein Quell des Lebens, ertrinkt es nun in einer Flut abscheulicher Kreaturen, die seine Macht stehlen. Und auch, wenn wir den Hain niemals zurückerobern, muss dieses Treiben ein Ende haben.\n\nStellt Euch dieser Prüfung und vernichtet die Eindringlinge in Tirna Scithe.", sourceObjective = "Schließt die Weltquest \"Schrecken in Tirna Scithe\", den Dungeon \"Nebel von Tirna Scithe\" oder den Dungeon \"Die Andre Seite\" im Ardenwald ab.", completion = "Stille hat sich über den Hain gesenkt, die Blätter rauschen nicht länger vor Pein. Das verdanken wir allein Euch, und wir werden diesen großen Dienst niemals vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60439] = { id = 60439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen im Ardenwald", description = "Unsere treuen Verbündeten im Ardenwald sehen sich mit Gefahren konfrontiert, die alles in den Schatten stellen, was sie bisher in ihren friedlichen Hainen erlebt haben.\n\nMacht Eure Waffen bereit, denn jetzt ist die Stunde gekommen, in der die goldenen Schilde der Bastion in den Kampf ziehen. Geht in den Ardenwald und zeigt, dass Euer Mut jeder Dunkelheit trotzt.\n\nDenn es dreht sich nicht alles immer nur um uns. Wahrer Mut ist, wenn man für jene kämpft, die sich nicht selbst helfen können. Auch gegen die größte Übermacht oder das abgrundtiefe Böse.\n\nDas Licht erstrahlt am hellsten in der Dunkelheit.", sourceObjective = "Schließt die Weltquest \"Schrecken in Tirna Scithe\", den Dungeon \"Nebel von Tirna Scithe\" oder den Dungeon \"Die Andre Seite\" im Ardenwald ab.", completion = "Ich habe von Euren großen Taten im Ardenwald gehört. Sie sind Euch für diesen Dienst sehr dankbar. Ihr habt Euren Mut heute zehnfach unter Beweis gestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60440] = { id = 60440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen im Ardenwald", description = "Wollt Ihr Euch beweisen? Ich habe gehört, mächtige Kreaturen sind in den Ardenwald eingefallen. Klingt nach einer Herausforderung, oder?\n\nAlso hoch die Waffen und auf in den Kampf! Wo solltet Ihr Eure Macht wohl besser beweisen?\n\nHaut sie in Stücke! Im Namen von Maldraxxus!", sourceObjective = "Schließt die Weltquest \"Schrecken in Tirna Scithe\", den Dungeon \"Nebel von Tirna Scithe\" oder den Dungeon \"Die Andre Seite\" im Ardenwald ab.", completion = "Ein Jammer, dass Eure Aufgabe so schnell vorbei war. So viele Feinde, so wenig Zeit!\n\nIhr seid ein echter Gewinn für unsere Truppen. Eure Kampfeslust gefällt mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[60441] = { id = 60441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen im Ardenwald", description = "Der Ardenwald war früher ein Hort des Friedens und der Erneuerung. Aber das ist vorbei.\n\nDer Feind greift den Wald von allen Seiten an. Finstere Kreaturen, die keinem Meister dienen.\n\nAber sie werden der Gerechtigkeit nicht entfliehen. Das Urteil von Revendreth kommt schnell und endgültig.\n\nSie werden sehen, wie wir Frevel und Aufruhr bestrafen.\n\nIch beschuldige diese Seelen der Sünden gegen die Schattenlande. Lasst Gerechtigkeit walten. Im Namen von Revendreth.", sourceObjective = "Schließt die Weltquest \"Schrecken in Tirna Scithe\", den Dungeon \"Nebel von Tirna Scithe\" oder den Dungeon \"Die Andre Seite\" im Ardenwald ab.", completion = "Heute haben die meisterlosen Kreaturen eine wichtige Lektion gelernt.\n\nLetztendlich sind wir ihre Meister.", sourceObjectiveStatus = "unverified-source-field" }
quests[60442] = { id = 60442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in der Bastion", description = "Manchmal finden sich große Herausforderungen direkt in unseren eigenen goldenen Hügeln.\n\nZweifel hat die Gedanken einiger der tapfersten kyrianischen Schildträger vergiftet und sie gegen uns aufgewiegelt. So können sich die Schattenlande nicht von dieser Verseuchung erholen.\n\nWir müssen ihnen die Stirn bieten. Hier und jetzt.\n\nEs wird nicht einfach, aber das sind wohl die wenigsten Dinge, für die es sich zu kämpfen lohnt.", sourceObjective = "Schließt die Weltquest \"Treulose Einwohner\", den Dungeon \"Spitzen des Aufstiegs\" oder den Dungeon \"Die Nekrotische Schneise\" in der Bastion ab.", progress = "Habt Ihr das Antlitz des Zweifels gesehen und ihm mit Entschlossenheit getrotzt?", completion = "Ihr habt die Saat des Zweifels mit dem Hammer der Entschlossenheit zermalmt. Mögen sich all ihre Zweifel jetzt nur noch um ihren eigenen dunklen Weg ranken.", sourceObjectiveStatus = "unverified-source-field" }
quests[60443] = { id = 60443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in der Bastion", description = "Die Bewohner der Bastion sind für uns so etwas wie Verbündete. Ohne ihre Dienste hätten wir keine Seelen. Ohne Seelen könnten wir keine Armeen aufstellen. Ohne Armeen könnten wir nicht unsere Fäuste in dieser glorreichen Arena des Kampfes schwingen!\n\n<Großmeister Vole lacht und schmettert mit seiner Waffe um sich.>\n\nWir müssen ihnen gegen ihre Feinde beistehen oder diese Arena bleibt leer wie mein Grab... und das können wir ja nicht zulassen!\n\nFindet ihre stärksten Feinde und zertrümmert ihre Knochen zu goldenem Staub.", sourceObjective = "Schließt die Weltquest \"Treulose Einwohner\", den Dungeon \"Spitzen des Aufstiegs\" oder den Dungeon \"Die Nekrotische Schneise\" in der Bastion ab.", completion = "Ihr seid zurück, siegreich und auf einem Berg blutiger Federn! Haha! Glorreich!", sourceObjectiveStatus = "unverified-source-field" }
quests[60444] = { id = 60444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in der Bastion", description = "Unsere Verbündeten in der Bastion dienen seit Langem dem Zyklus der Schattenlande und liefern Seelen, die unserer Aufmerksamkeit bedürfen.\n\nAber dennoch breitet sich in ihren Reihen Zweifel aus wie eine schwärende Wunde. Wenn das so weitergeht, werden wir alle dafür bezahlen.\n\nDieser Mangel an Pflichtbewusstsein muss ein Ende haben. Wir werden diese abtrünnigen Herzen bestrafen.\n\nIch beschuldige diese Seelen der Sünde gegen die Schattenlande. Lasst im Namen von Revendreth Gerechtigkeit walten.", sourceObjective = "Schließt die Weltquest \"Treulose Einwohner\", den Dungeon \"Spitzen des Aufstiegs\" oder den Dungeon \"Die Nekrotische Schneise\" in der Bastion ab.", completion = "Die Sünden der Zweifler sind geläutert.", sourceObjectiveStatus = "unverified-source-field" }
quests[60445] = { id = 60445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in Maldraxxus", description = "Der Zweck von Maldraxxus ist es, die fähigsten und zuversichtlichsten Krieger aller Zeiten in den Schattenlanden heranzuziehen und die perfekte Armee zu schaffen, um uns gegen Bedrohungen von außen zu verteidigen.\n\nHier findet Ihr einige unserer größten Herausforderungen.\n\nSucht die Champions der stärksten Häuser, tretet gegen sie an und zeigt ihnen Eure Stärke.", sourceObjective = "Schließt die Weltquest \"Auserwählte Champions\", den Dungeon \"Theater der Schmerzen\" oder den Dungeon \"Seuchensturz\" in Maldraxxus ab.", completion = "Ihr steht allein als ein wahrer Meister des Kampfs auf einem Haufen Knochen. Ihr habt Euch heute als echter Nekrolord erwiesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[60446] = { id = 60446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in Maldraxxus", description = "Aus Maldraxxus stammen die auserwählten Krieger der Schattenlande, die uns gegen Bedrohungen von außen verteidigen sollen.\n\nSeit vielen Jahren wird ein sorgfältiges Gleichgewicht zwischen den Häusern aufrechterhalten. Nun gibt es diejenigen, die dieses Gleichgewicht gestört haben und wir sind alle geschwächt und schutzlos.\n\nSie müssen für diese Übergriffe bezahlen.\n\nIch klage diese Seelen der Sünden gegen die Schattenlande an. Tretet im Namen von Revendreth für Gerechtigkeit ein.", sourceObjective = "Schließt die Weltquest \"Auserwählte Champions\", den Dungeon \"Theater der Schmerzen\" oder den Dungeon \"Seuchensturz\" in Maldraxxus ab.", completion = "Möge ihnen das als Lektion dafür dienen, dass Revendreth nicht untätig zusieht, wie das Gleichgewicht gestört wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[60447] = { id = 60447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in Maldraxxus", description = "In Maldraxxus hat das Haus der Auserwählten große Landstriche an sich gerissen und das Gleichgewicht der Kräfte unter den Häusern gestört. Die stärksten Gladiatoren und Krieger schließen sich in Scharen den Auserwählten an.\n\nWelcher Ort wäre besser geeignet, um Euer Geschick zu testen?\n\nZieht hinaus in das Land von Knochen und Blut und stellt Euch ihren mächtigsten Schergen. Stellt die Stärke unter Beweis, die in Eurem Inneren ruht.", sourceObjective = "Schließt die Weltquest \"Auserwählte Champions\", den Dungeon \"Theater der Schmerzen\" oder den Dungeon \"Seuchensturz\" in Maldraxxus ab.", completion = "Euer Arm hat auch die stärksten Gladiatoren gefällt. Jetzt wissen alle, dass auch wir die Schattenlande beschützen, wenn es notwendig ist. Mögen sie diese Lektion nie vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60448] = { id = 60448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in Revendreth", description = "Wer im Namen von Graf Denathrius und dem Kerkermeister gegen uns die Waffen erhoben hat, hat uns allen den Rücken gekehrt.\n\nEinige sind nur Schachfiguren in diesem Spiel, andere befehligen sie. Die Anführer in dieser Krise tragen die größte Verantwortung.\n\nSie sind die mächtigsten Verbündeten von Denathrius und müssen vor Gericht gestellt werden.\n\nIch klage diese Seelen der Sünden gegen die Schattenlande an. Tretet im Namen von Revendreth für Gerechtigkeit ein.", sourceObjective = "Schließt die Weltquest \"Die Dominanz vernichten\", den Dungeon Die Blutigen Tiefen oder den Dungeon Hallen der Sühne in Revendreth ab.", completion = "Der Gerechtigkeit wurde Genüge getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[60449] = { id = 60449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in Revendreth", description = "Ich habe den Venthyr von Revendreth nie wirklich getraut. Vielleicht sind es ihre langen Mäntel oder vielleicht diese spitzen Zähne, aber irgendetwas an ihnen macht mir Angst.\n\nIhr Anführer, Denathrius, hat sich auf die Seite des Kerkermeisters und gegen uns gestellt, also hatte ich wohl Recht.\n\nIch will, dass Ihr seine mächtigsten Verbündeten in Revendreth findet und sie zu blutigem Brei schlagt. Sendet ihm eine Botschaft von Maldraxxus.", sourceObjective = "Schließt die Weltquest \"Die Dominanz vernichten\", den Dungeon Die Blutigen Tiefen oder den Dungeon Hallen der Sühne in Revendreth ab.", completion = "Ich habe von Euren blutigen Heldentaten in Revendreth gehört und bin sehr zufrieden.\n\nHabt Ihr mir ein paar ihrer Zähne mitgebracht? Nein? Nun, dann vielleicht nächstes Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[60450] = { id = 60450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderungen in Revendreth", description = "Euch selbst ständig neue Herausforderungen zu suchen, ist ein wichtiger Schritt auf dem Weg zum Aufstieg. Denn was zählt schon Mut unter normalen Umständen?\n\nIn diesen unruhigen Zeiten gibt es mehr als genug Möglichkeiten, Euch selbst zu beweisen. Seht es als goldenen Streif an einem düsteren Horizont.\n\nUnd auf keinen Ort trifft das mehr zu als auf Revendreth. Dort mehrt Graf Denathrius stetig Macht und Einfluss, um die natürliche Ordnung der Schattenlande umzustürzen.\n\nGenau dort werdet Ihr Euch heute Eurer Herausforderung stellen.", sourceObjective = "Schließt die Weltquest \"Die Dominanz vernichten\", den Dungeon Die Blutigen Tiefen oder den Dungeon Hallen der Sühne in Revendreth ab.", completion = "Selbst so fern von unseren Feldern wart Ihr ein unerschütterliches Bollwerk gegen das Böse. Das zeugt von wahrem Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[60451] = { id = 60451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemals genug", description = "Gut gemacht, Rekrut. Das waren nur die ersten Aufträge, viele werden in der Zukunft folgen.\n\nAngelegenheiten hier erfordern meine Aufmerksamkeit. Meldet Euch bei Baronin Draka und seht, wofür sie Euch braucht.\n\nIch werde die Ereignisse dieses Krieges genau verfolgen.", sourceObjective = "Kehrt zu Baronin Draka zurück.", completion = "Gute Arbeit. Ich kann sehen, dass unsere Verteidigung verstärkt wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[60452] = { id = 60452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf den Schlund", description = "Oh, nein. Nein, nein, nein. Der Kerkermeister hat sich alle Seelen geschnappt und jetzt auch noch einen Riesenvorrat Anima! Wer weiß, was er damit anstellt!\n\nIhr müsst sofort dahin zurück! Ihr seid <der Schlundgänger/die Schlundgängerin>!\n\nFindet alles über seine Macht heraus, was Ihr könnt, und haltet ihn auf, wo immer es geht. Ich glaube an Euch!\n\nUnd seid vorsichtig, verstanden?", sourceObjective = "Tötet 3 seltene oder besondere Begegnungsbosse im Schlund.", completion = "Das habt Ihr gut gemacht! Eure Berichte haben uns sehr geholfen. Klingt so, als hättet Ihr dort ganze Arbeit geleistet. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[60453] = { id = 60453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zum Ruhm", description = "Es ist einige Zeit her, dass ich die Gelegenheit hatte, so eine mächtige Waffe zu schmieden! Gut zu wissen, dass das, was ich vom Primus gelernt habe, sich nicht abgenutzt hat.\n\nIhr kehrt mit dieser Runenklinge besser zu der Baronin zurück. Der Markgraf will sicher ebenfalls wissen, dass Ihr sie führt.\n\nDer Primus war bekannt dafür, dass er jedem immer zehn Schritte voraus war. Ich vermute, er wusste, dass jemand wie Ihr diese Klinge beanspruchen würde.", sourceObjective = "Kehrt mit Eurer Runenklinge zu Baronin Draka zurück.", completion = "Ihr führt eine gute Waffe. Jetzt müsst Ihr sie einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60454] = { id = 60454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf den Schlund", description = "Bisher konnten wir kaum etwas tun, um den Strom der Seelen in den Schlund einzudämmen. Aber Ihr, <Schlundgänger/Schlundgängerin>, Ihr könnt dem ein Ende setzen.\n\nWir wissen kaum etwas über das Land des Kerkermeisters, nur dass er selbst unvorstellbar mächtig ist.\n\nIch habe heute eine Aufgabe für Euch, die ich sonst niemandem anvertrauen würde. Ihr müsst in dieses Land reisen und alles tun, damit seine Streitmacht nicht noch größer wird.\n\nWir müssen Zeit gewinnen.", sourceObjective = "Tötet 3 seltene oder besondere Begegnungsbosse im Schlund.", completion = "Ihr habt uns viele Dinge gezeigt, die wir niemals selbst entdeckt hätten. Vielleicht können wir jetzt einen Plan ausarbeiten.\n\nHeute habt Ihr uns wahrlich einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60455] = { id = 60455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf den Schlund", description = "Wir dürfen nicht zulassen, dass der Kerkermeister an Macht gewinnt. Ihr allein könnt den Kampf in sein Land tragen und Ihr müsst es tun, sonst werden wir alle fallen.\n\nKehrt in sein Land zurück, <Schlundgänger/Schlundgängerin>. Er hat bereits seine Karten auf den Tisch gelegt, und wir wissen, dass er jeden Tag mächtiger wird.\n\nSeine Streitkräfte müssen aufgehalten werden. Erzielt in dieser Hinsicht so viele Fortschritte wie möglich.", sourceObjective = "Tötet 3 seltene oder besondere Begegnungsbosse im Schlund.", completion = "Er hat Euch gesehen, und jetzt seid Ihr markiert. Betrachtet es als Ehrenabzeichen. Niemand sonst hätte das tun können, was Ihr getan habt.\n\nNoch hat er keine Angst, aber das wird er bald.", sourceObjectiveStatus = "unverified-source-field" }
quests[60456] = { id = 60456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf den Schlund", description = "Wir wissen nur wenig über den Schlund, <Schlundgänger/Schlundgängerin>. Nur Ihr habt die Macht, dieses Land zu bereisen und wieder zurückzukehren.\n\nIch würde nie wagen, das, worum ich Euch jetzt bitte, von jemand anderem zu verlangen.\n\nWir dürfen nicht zulassen, dass der Kerkermeister an Macht gewinnt. Ihr müsst zum Schlund reisen und sein Land angreifen.\n\nBemüht Euch um so viel Fortschritt wie möglich, wir müssen seine Streitkräfte auf jede erdenkliche Art verlangsamen.", sourceObjective = "Tötet 3 seltene oder besondere Begegnungsbosse im Schlund.", completion = "Wir haben viel von Euren Reisen in den Schlund gelernt und wir werden für die Zukunft planen.\n\nEs gab keine andere Möglichkeit, den Kerkermeister an der Festigung seiner Macht zu hindern, Ihr habt uns einen großen Dienst erwiesen, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[60457] = { id = 60457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animabergung", description = "So viele Seelen, die unter unsere Obhut hätten fallen sollen, sind im Schlund verloren. Allein der Gedanke bereitet mir große Qual.\n\n<Schlundgänger/Schlundgängerin>, wir bitten Euch, heute das zu tun, was wir nicht können. Dringt in das Reich des Kerkermeisters ein, durchquert seine verdorrten Felder und erklimmt seinen verfluchten Turm.\n\nBringt uns, woran uns mangelt.", sourceObjective = "Sammelt 150 Animafunken in Torghast, Turm der Verdammten.", progress = "Habt Ihr die Animafunken beschaffen können?", completion = "Ihr habt uns heute einen großen Dienst erwiesen, Schlundgänger. Damit werden wir so viele versorgen, wie wir können.", sourceObjectiveStatus = "unverified-source-field" }
quests[60458] = { id = 60458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animabergung", description = "Als wir Seelen zur Richterin überführten, hätten wir uns nie träumen lassen, dass so etwas je geschehen könnte. Voller Verzweiflung mussten wir mitansehen, wie sie in den Schlund gestoßen wurden. Eine nach der anderen. Dann Hunderte. Und dann Tausende.\n\nSeelen, die verschlungen und aufgezehrt wurden und deren Anima für uns verloren ist. Bringt zu uns zurück, was Ihr könnt.", sourceObjective = "Sammelt 150 Animafunken in Torghast, Turm der Verdammten.", progress = "Habt Ihr die verlorenen Animafunken gefunden?", completion = "Es ist zwar nicht das Gleiche, als wären ihre Seelen zurückgebracht worden, aber ihre Kraft soll nicht verschwendet sein. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[60459] = { id = 60459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animabergung", description = "Die Richterin hat uns einen großen Bärendienst erwiesen. Unsere Armeen schrumpfen, weil Seelen in den Schlund geworfen werden, statt ihren Platz auf den Schlachtfeldern von Maldraxxus einzunehmen.\n\nDie Unvergängliche Armee darf nicht ausgelöscht werden. Wenn die Schattenlande überleben sollen, müssen wir unsere Truppen versorgen können.\n\nReist jetzt in den Schlund, <Schlundgänger/Schlundgängerin>, und dringt in Torghast ein. Bringt uns diese Animafunken zurück, damit wir unsere Vorräte auffüllen können.", sourceObjective = "Sammelt 150 Animafunken in Torghast, Turm der Verdammten.", progress = "Habt Ihr Animafunken für unsere Vorräte mitgebracht?", completion = "Die Armeen der Unsterblichen werden heute nicht fallen, Schlundgänger. Erneut geht Ihr siegreich aus dem Kampf gegen eine große Macht hervor... Beeindruckend.", sourceObjectiveStatus = "unverified-source-field" }
quests[60460] = { id = 60460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animabergung", description = "Revendreth ist kein Ort, den viele Seelen freiwillig wählen, aber es ist ein Ort, an den sie gehen müssen. Hier werden sie schonungslos mit ihren Sünden konfrontiert. Sie werden gebrochen und neu geformt, um in unsere Gesellschaft eingegliedert zu werden.\n\nDas ist ein notwendiger Teil des Kreislaufs.\n\nAber jetzt ist der Kreislauf gebrochen und sie sind unfähig, unserem großen Zweck zu dienen.\n\nWir benötigen Anima, um unsere Arbeit verrichten zu können. Reist nach Torghast, <Schlundgänger/Schlundgängerin>, und sammelt das, was wir nicht können. Ohne sie verwelken und verblassen wir.", sourceObjective = "Sammelt 150 Animafunken in Torghast, Turm der Verdammten.", progress = "Habt Ihr uns die Animafunken gebracht?", completion = "Diese Animafunken werden uns gute Dienste leisten, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[60461] = { id = 60461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft den Markgrafen", description = "Kunde von der Runenklinge hat Markgraf Krexus erreicht. Er möchte sie selbst sehen.\n\nMit so einer Waffe stellt Ihr eine Bedrohung dar, die die anderen Häuser nicht ignorieren können. Vielleicht können wir das zu unserem Vorteil nutzen.\n\nAber genug geredet. Folgt mir.", sourceObjective = "Zeigt Markgraf Krexus Eure Runenklinge.", completion = "Zeigt mir Eure Runenklinge, Sterblicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[60462] = { id = 60462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animaambulanz", description = "<Schlundgänger/Schlundgängerin>!\n\nDas Animareservoir ist fast erschöpft. Ohne weitere Anima werden die Haine bald verdorren und sterben.\n\nDurchsucht die Reiche nach zusätzlicher Nahrung und liefert sie beim Sanktum ab.\n\nDer Ardenwald kann ohne Eure Hilfe nicht weitermachen!", sourceObjective = "Lagert 600 Anima im Animareservoir im Herz des Waldes im Ardenwald ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60463] = { id = 60463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animaambulanz", sourceObjective = "Lagert 600 Anima im Animareservoir in Sündensturz in Revendreth ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60464] = { id = 60464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animaambulanz", description = "<Schlundgänger/Schlundgängerin>! Unsere Animareserven sind fast erschöpft. Ohne einen zusätzlichen Vorrat an Anima wird unsere Eroberungsmission scheitern!\n\nDurchkämmt die Reiche nach so viel Anima, wie Ihr sammeln könnt und bringt sie hierher ins Sanktum.\n\nDer Sieg hängt davon ab, dass Ihr erfolgreich seid!", sourceObjective = "Lagert 600 Anima im Animareservoir im Sitz des Primus in Maldraxxus ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60465] = { id = 60465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animaambulanz", description = "<Schlundgänger/Schlundgängerin>!\n\nUnser Vorrat an Anima geht zur Neige und das Reservoir ist fast erschöpft. Wir müssen unsere Reserven wieder auffüllen, bevor es zu spät ist!\n\nSucht in den Reichen nach so viel Anima, wie Ihr sammeln könnt und bringt sie zum Sanktum.\n\nDie Zeit ist knapp. Beeilt Euch, {class}.", sourceObjective = "Lagert 600 Anima im Animareservoir in der Elysischen Feste in der Bastion ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60466] = { id = 60466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die alten Gepflogenheiten", description = "Ihr da! Darf ich Euch um Hilfe bitten?\n\nIch muss zugeben, dass durch den Mangel neuer eintreffender Seelen unsere Vorräte zur Neige gehen. Uns fehlen die Mittel, um Neuankömmlinge nach Art der Kyrianer einzukleiden.\n\nBevor die Zenturionen geschmiedet wurden, haben die Aspiranten die hiesigen Wildtiere für ihr Training genutzt. Vielleicht gibt es noch eine andere Weise, auf die diese Tiere sich nützlich erweisen können.\n\nWenn Ihr Material von den Wolkenwanderern und Larions in der Umgebung sammelt, können wir damit dafür sorgen, dass unsere Neuankömmlinge angemessen ausgestattet werden.\n\nOh, und etwas Garn von Mirene, wenn es Euch nichts ausmacht!", sourceObjective = "Besorgt Euch elysischen Faden, 4 Wolkenwandererpelze und 12 Larionfedern.", progress = "Wie verläuft die Jagd?", completion = "Einfach perfekt! Geht und dient, zu jeder Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[60467] = { id = 60467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufrüttelndes Aroma", description = "<Sabina reagiert nicht. Ihr freiliegendes Fleisch ist rissig und voller Blasen. Vielleicht wird ein scharfes Aroma sie aufwecken.>", sourceObjective = "Sammelt 4 Einheiten stechendes Schwärmertoxin von gefräßigen Schwärmen.", progress = "Sabina ist weiterhin nicht ansprechbar.", completion = "<Sabina regt sich.>\n\nSind... Sind sie wieder da? Helft... helft mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[60468] = { id = 60468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wühlen im Schutt", description = "Ich weiß nicht, wie lange es her ist, dass meine Entführer mich hier zurückgelassen haben, aber das Licht... hat mir sehr zugesetzt.\n\nIhr müsst mir helfen, zu fliehen. Der Schlüssel zu meinen Fesseln sollte in der Nähe versteckt sein. Vielleicht in dem Schutt? Dort würde ich wahrscheinlich etwas Kleines verstecken.", sourceObjective = "Findet einen Fesselschlüssel in dem Schutt im Aschegang.", progress = "Habt Ihr den Schlüssel gefunden?", completion = "Sieht aus, als könnte er passen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60469] = { id = 60469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicher in den Schatten", description = "Ich kann mich nicht erinnern, was passiert ist. Vielleicht hat das Licht mein Gedächtnis beeinträchtigt? Wer weiß, wie lange ich schon hier draußen bin...\n\nDas Letzte, woran ich mich erinnere, bevor es dunkel wurde... meine Gefährten und ich hatten endlich Zuflucht im Schatten gefunden. Ich bin um ihr Wohlergehen besorgt.\n\nSolange meine Angreifer auf freiem Fuß sind, könnten meine Gefährten in Gefahr sein. Werdet Ihr sie finden und dafür sorgen, dass sie sich noch sicher in den Schatten befinden?", sourceObjective = "Findet heraus, was mit Sabinas Begleitern geschehen ist.", completion = "Sie sind verstorben? Seid Ihr sicher? Wer hätte etwas so Grausames tun können...", sourceObjectiveStatus = "unverified-source-field" }
quests[60470] = { id = 60470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabina freilassen", description = "Lasst mich frei. Bitte, Ihr müsst das tun. Ich kann nicht länger im Licht verweilen.\n\nDieses Unbehagen, es ist so... vertraut, aber es wird vorübergehen. Ich werde wieder ich selbst sein, sobald ich in die Schatten zurückgekehrt bin.\n\nIch werde auch mucksmäuschenstill sein und mich nicht regen, während Ihr am Schloss arbeitet.", sourceObjective = "Befreit Sabina von ihren Fesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[60474] = { id = 60474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spawn Tracking Unit-Specified World Effect in a WMO Bug", description = "Es scheint einen Fehler zu geben, wenn man einen Welteffekt mit einem goldenen Punkt auf der Minikarte über das Spawntracking erstellt, der auf Einheit statt auf Ziel eingestellt ist. Das scheint nur bei Spawns innerhalb von WMOs zu passieren. Könnte auch passieren, wenn man ihn auf Objekt einstellt.\n\nWenn das Spawntracking des Welteffekts auf Ziel eingestellt ist, ist alles in Ordnung. Wenn er jedoch auf Einheit eingestellt ist, wird der Goldpunkt nicht auf der Minikarte angezeigt.", sourceObjective = "Versucht herauszufinden, warum der goldene Punkt des WMO-Spawnziels auf der Minikarte nicht auftaucht, wenn das Spawntracking auf Einheit statt Ziel eingestellt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[60475] = { id = 60475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir arbeiten daran" }
quests[60476] = { id = 60476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit zur Sprigganisierung!" }
quests[60480] = { id = 60480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Endmorast", description = "Ey! Ihr da!\n\nWeiß ja nicht, wie Ihr im Endmorast gelandet seid, aber ich brauche Eure Hilfe.\n\nSeht Ihr die Fackeln? Ich muss drauf achten, dass sie nicht ausgehen. Aber es ist ja nicht so, dass dafür Feuerstein und Zunder reichen.\n\nMein Vorrat an durchfluteten Rubinen wurde von ein paar Verschlingern weggeschleppt, als ich mal nicht aufgepasst hab. Könnt Ihr sie finden, bevor wir beide von einem dieser Schrecken gefressen werden?", sourceObjective = "Findet 5 durchflutete Rubine.", progress = "Ich will's mal ganz deutlich sagen: ICH... HASSE... ES... EINFACH.", completion = "Besten Dank. Diese Fackeln halten die Auswirkungen des Endmorasts in Schach. Schrecken sogar die Verschlinger kurzzeitig ab. Hält aber nicht sehr lange.\n\nMir fehlt die gute alte Zeit, in der ich mich hier unten nur mit Manifestationen rumschlagen musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[60482] = { id = 60482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht mit meinen Augen", description = "Nach der Zerstörung unseres Hauses wurden die Spinnen in der Gegend zunehmend feindselig. Sie dehnen ihr Reich aus und lauern auf die wenigen Überlebenden dort. \n\nEs gibt Waffen, mit denen wir uns schützen könnten, aber sie liegen in der Augenlosen Festung verborgen. Die Netze ihrer neuen Bewohner bedecken sie.\n\nReist zur Festung, benutzt meine augenlose Sicht, um die Waffen zu sehen und holt zurück, was Ihr könnt.", sourceObjective = "Sammelt 10 versteckte Waffen.", progress = "Habt Ihr die Waffen zurückgeholt?", completion = "Ihr könnt noch mehr von ihnen erledigen, wenn Ihr möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[60487] = { id = 60487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es war so schön ruhig hier", description = "Nun... Ihr seht nicht wie die anderen aus, oder?\n\n<Meißelmurr zuckt mit den Schultern.>\n\nMacht mir nichts. Zieh meinen Kopf ein, mach meine Arbeit und sorge dafür, dass diese Sündensteine in guter Form bleiben.\n\nMir zerbrechen aber dauernd die Werkzeuge.\n\nHolt mir noch ein paar Meißel und ich bring Euch einen alten Gräberkonstruktionstrick bei.", sourceObjective = "Sammelt 8 Gräbermeißel.", progress = "Habt Ihr die Meißel schon?", completion = "Ja, die werden 'ne Weile halten.\n\nAlso schön, ich zeig Euch den Trick, wie man schnell eine Barrikade baut...", sourceObjectiveStatus = "unverified-source-field" }
quests[60489] = { id = 60489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Aufstiegs", description = "Dank der Anima, die Ihr gesammelt habt, können wir erneut mit dem Pfad des Aufstiegs beginnen.\n\nAls ewiges Übungsgelände der Kyrianer ist der Pfad eine uralte Tradition, die von vielen mit Begeisterung gepflegt wird, sowohl von Aspiranten als auch von Aufgestiegenen.\n\nDie Hände des Mutes, Apolon und Artemede, leiten nun diese Tradition. Sprecht mit ihnen, wenn Ihr die Wiedergeburt des Pfades verkündet, um mehr zu erfahren.", sourceObjective = "Aktiviert den Pfad des Aufstiegs.", completion = "Dank Euch fließt wieder Anima durch das Kolosseum. Großer Ruhm erwartet Euch und Eure Verbündeten auf dem Pfad des Aufstiegs!", sourceObjectiveStatus = "unverified-source-field" }
quests[60491] = { id = 60491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Kyrianern", description = "Ab heute sind die Kyrianer Eure neue Familie, <Bruder/Schwester>. Eure Hilfe ist willkommen.\n\nDie Archon war von diesem Ausgang so überzeugt, dass sie Euch zu Ehren einen großen Empfang vorbereitet hat, um all Eure Unterstützung gegen die maldraxxische Invasion in unser Reich zu würdigen.\n\nAber geht zunächst einmal zum Sitz der Ewigen Hymnen. Ich werde Euch dort erwarten.", sourceObjective = "Trefft Polemarch Adrestes am Sitz der Ewigen Hymnen in der Bastion.", completion = "Vieles findet in diesem Moment seinen Höhepunkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60492] = { id = 60492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein angemessener Empfang", description = "Der Pfad, dem Ihr folgt, ist zwar nicht der Pfad der traditionellen Aufgestiegenen, aber es ist dennoch ein Pfad der Kyrianer.\n\nIhm zu folgen, bedeutet, den Fußspuren der unzähligen Leben vor uns zu folgen, immer im Dienst einer größeren Sache, die wir allein nicht erreichen können.\n\nDass Ihr Euch uns inmitten solcher Unruhe anschließt, ist lobenswert. Unsere Archon hat uns allen befohlen, Euch wie sie selbst in unseren Reihen zu begrüßen.", sourceObjective = "Schließt Euch dem Pakt der Kyrianer an.", progress = "Dies ist der letzte Schritt, um Euch in unsere Reihen aufzunehmen. Wenn Ihr noch Zweifel habt, dann äußert sie jetzt.", completion = "Möge dies nur der Anfang sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60493] = { id = 60493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelwut", description = "Bevor Eure Seelenbande einen Fuß in das Kolosseum setzen, müsst Ihr Euren ersten Gegner herausfordern.\n\nGenau wie für alles gibt es auch hier eine Tradition. Ihr müsst bestimmte Gegenstände sammeln, hierherbringen und daraus Waffen für Eure Herausforderung bauen.\n\nDie Materialien für Eure erste Herausforderung findet Ihr überall in der Bastion. Kehrt zu mir zurück, wenn Ihr alles habt. Dann folgt der nächste Schritt.", sourceObjective = "Sammelt 2 ausgelaugte Goliathkerne von Goliaths der Verschmähten, 6 manipulierte Animalader von Zenturionen der Verschmähten und 5 Seelenspiegelscherben von verschmähten Kyrianern.", progress = "Auch wenn der Pfad des Aufstiegs zu großem Ruhm führt, müssen Teilnehmer stets bescheiden bleiben und die Traditionen achten.", completion = "Ihr habt die ersten Schritte getan. Eine bemerkenswerte Leistung!", sourceObjectiveStatus = "unverified-source-field" }
quests[60494] = { id = 60494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Freundin Dactylis", description = "Mit den von Euch gesammelten Materialien könnt Ihr nun Euren Köder fertigen.\n\nMeldet Euch bei Dactylis. Sie kann Euch nicht nur bei dieser Aufgabe helfen, sondern auch bei der Herstellung aller möglichen anderen Dinge. Aber das kommt später.\n\nSobald Euer Köder fertig ist, kehrt zu mir zurück und ich sage Euch, wie es weitergeht.", sourceObjective = "Sprecht mit Dactylis, um 2 überladene Goliathkerne und 1 Seelenspiegel herzustellen.", progress = "Inspiriert durch die Sammler müssen wir uns die Zeit nehmen, Dinge von Hand zu fertigen. Durch Handwerk üben wir uns in Geduld, Fleiß und Demut.", completion = "Jedes Mal, wenn Ihr etwas von Hand fertigt, geht ein Teil von Euch in das Objekt über.", sourceObjectiveStatus = "unverified-source-field" }
quests[60495] = { id = 60495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der richtige Gegner", description = "Die Gegner, gegen die Ihr im Kolosseum trainiert, sind keine körperlichen Wesen, sondern Manifestation von solchen.\n\nEurem ersten Gegner seid Ihr und Eure Seelenbande schon oft begegnet... der Aufgestiegenen Kalisthene.\n\nEs ist eine große Ehre für andere Kyrianer, wenn Ihr sie darum bittet, auf dem Pfad Euer Gegner zu sein, weil es zum Ausdruck bringt, dass Ihr noch vieles von ihnen lernen könnt.\n\nGeht zum Erwachen des Aspiranten und verwendet die Kerne, um Kalisthene zu beschwören, indem Ihr Euch ins Gedächtnis ruft, wie Ihr Euch vorgestellt wurdet. So will es die Zeremonie.", sourceObjective = "Benutzt die überladenen Goliathkerne bei den ausgelaugten Goliaths im Erwachen des Aspiranten und fangt dann mit dem Seelenspiegel eine Erinnerung an Kalisthene ein.", completion = "Kalisthene wird Eure Freunde gut ausbilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60496] = { id = 60496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Kolosseum", description = "Die Zeit Eurer Herausforderung ist gekommen!\n\nDa Ihr nicht aus der Bastion stammt, werdet Ihr als <Taktiker/Taktikerin> für Eure Seelenbande fungieren. Eure Bindung ist inzwischen sehr stark... also lasst uns sehen, wie sie mit dem Kolosseum zurechtkommen.\n\nSagt mir einfach, wenn Ihr beginnen wollt. Zeigt uns, wie stark Eure Bande sind!", sourceObjective = "Sprecht mit Artemede, um den Pfad des Aufstiegs in Angriff zu nehmen.", progress = "Das ist lediglich die erste in einer langen Reihe von Herausforderungen für Euch, {name}. Vergesst das nie und bleibt bescheiden.", completion = "Eine Lektion in Demut. Aber nichts geschieht ohne Sinn.\n\nDieser Bauplan wird Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60497] = { id = 60497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fußpolster des Herolds", description = "Manchmal ist reine Willensstärke einfach nicht genug. Die richtige Ausrüstung kann Euch das Leben retten.\n\nDieser Bauplan, den Ihr gefunden habt, kann Euch beibringen, wie Ihr Euer erstes Ausrüstungsstück herstellt.\n\nBringt ihn zu Dactylis. Sie kann Euch ebenfalls dabei helfen.", sourceObjective = "Bringt den Bauplan: Fußpolster des Herolds zu Dactylis.", progress = "Willkommen zurück. Wie kann ich Euch behilflich sein?", completion = "Ah, ein neuer Bauplan! Lasst uns anfangen, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[60498] = { id = 60498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung bewältigen", description = "Diese neuen Fußpolster könnten Pelagos den benötigten Vorteil verschaffen, um Kalisthene zu besiegen.\n\nKehrt zum Pfad zurück, {name}. Rüstet Pelagos mit diesen Fußpolstern aus und bezwingt Euren Gegner.\n\nEs braucht vielleicht mehr als einen Anlauf, aber das ist bei allen Prüfungen so.\n\nGeht und dient. In Ruhm und Ehre!", sourceObjective = "Besiegt Kalisthene auf dem Pfad des Aufstiegs.", completion = "Es warten noch weitere Prüfungen auf Euch, {name}. Ihr allein müsst entscheiden, was die Zukunft auf dem Pfad des Aufstiegs für Euch bereithält!", sourceObjectiveStatus = "unverified-source-field" }
quests[60500] = { id = 60500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Sühne: Medaillon des Stolzes", description = "Unsere Verhandlungsversuche wurden bestenfalls skeptisch aufgenommen. Die Medaillons zu beschaffen, könnte mehr Anstrengung erfordern, als ursprünglich beabsichtigt. Trotzdem ist nicht alle Hoffnung verloren.\n\nIch bin davon überzeugt, dass wir viele der Ernter für uns gewinnen können. Und für diejenigen, bei denen das nicht der Fall ist, müssen wir direkter vorgehen.\n\nDer Oberste Kämmerer fällt in diese Kategorie. Sein Medaillon muss mit Gewalt beschafft werden.", sourceObjective = "Beschafft das Medaillon des Stolzes vom Obersten Kämmerer in den Hallen der Buße.", progress = "Habt Ihr das Medaillon beschafft?", completion = "Hiermit sind wir der Wiederbelebung von Revendreth einen Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60501] = { id = 60501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlösung für den Erlöser", description = "<Die Energien des Todes und der Anregung kämpfen darum, sich von der Klinge zu befreien und Euch bis ins Innerste zu verzehren.>\n\n<Die Bande des Schutzes, die Prinz Renathal dieser Klinge auferlegt hat, werden nicht lange halten. Sie sollte nach Sündensturz gebracht werden, wo dauerhaftere Vorkehrungen für diese Gefangene getroffen wurden.>", sourceObjective = "Bringt Remornia zu General Draven am Rande von Sündensturz.\n\nBereitgestellter Gegenstand:", completion = "Denathrius diente einst einer edlen Sache. Seine charismatische Führung und sein Verständnis für die dunklen Begierden trugen zur Erlösung von mehr Seelen bei, als Eure Welt kannte.\n\nVielleicht könnte er mit der Zeit wieder so sein. Falls die richtigen Lektionen ihn an seine wahre Bestimmung erinnern würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60502] = { id = 60502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutige Tiefen: Ein Verbündeter im Inneren", description = "Es gibt Gerüchte über einen Gefangenen in diesen Tiefen, der für unsere Sache von Nutzen sein könnte.\n\nOb man sich auf diese Informationen verlassen kann, ist unbekannt. Es könnte sich genauso gut um eine Falle handeln, aber dennoch müssen wir dem nachgehen.\nWir können uns nicht leisten, eine Gelegenheit wie diese zu ignorieren.\n\nWagt Euch in die Blutigen Tiefen vor und rettet diesen wertvollen Gefangenen.", sourceObjective = "Rettet den wertvollen Gefangenen aus den Blutigen Tiefen.", completion = "Dieser Naaru wird sich als unschätzbarer Verbündeter erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60504] = { id = 60504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Band stärken", description = "Die Bindung der Seelen ist nur der erste Schritt. Ihr müsst jetzt ihr Potenzial ausloten.\n\nSo wie Pelagos Stärke von Euch bezieht, so werdet auch Ihr an ihm wachsen. Je weiter die Bindung mit der Zeit wächst, desto tiefer dringt Ihr in die Seele des anderen ein und desto mehr Stärke gewinnt Ihr.\n\nIhr müsst nur Eure Hand auf die Schmiede der Bande legen, um Euer Band zu verstärken. Dafür ist kein Preis zu zahlen. Die einzige Beschränkung ist Eure Verbindung zu unserem heiligen Pakt.", sourceObjective = "Aktiviert einen Seelenbandbonus, indem Ihr die Schmiede der Bande benutzt.", completion = "Möget Ihr Euch in den kommenden Prüfungen als würdige Verbündete erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60505] = { id = 60505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinnennest", description = "Als unser Haus zerfiel, nutzte Manipulator Zalisar die Gelegenheit, das Haus unter seiner Führung zu reformieren. Er fand neue Anhänger und verschwand bald darauf in den Ruinen in der Nähe.\n\nEr hat angefangen, die Spinnen zu manipulieren und als seine Soldaten auszubilden. Spinnen unter seiner Kontrolle haben begonnen, Jagd auf unsere Streitkräfte zu machen. Wir müssen dieser Bedrohung Herr werden, bevor es noch schlimmer wird.\n\nIhr müsst Manipulator Zalisar und seine Spinnenstreitkräfte eliminieren.", sourceObjective = "Tötet 8 Klingennetzweber und Manipulator Zalisar.", completion = "Eure Hilfe ist immer willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60506] = { id = 60506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anklägerin", description = "Es ist Zeit, unsere letzte Beute zu jagen, die Anklägerin.\n\nAnimadürre oder nicht, ihr kriecherisches Festhalten an heiligen \"Ritualen\" steht im Widerspruch zum Willen des Meisters. Ich kann es kaum erwarten, die Angst in ihren Augen zu sehen.", sourceObjective = "Jagt die Anklägerin.", completion = "So treffen wir uns wieder. Unter schwierigen Umständen, fürchte ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[60508] = { id = 60508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Fersen", description = "In meinen Visionen wurde ich Zeugin, wie Tyrande sich durch einen endlosen Strom aus bösartigen, alptraumartigen Wesen gemäht hat.\n\nDa vorne... Ist das...? Ja. Ich glaube, das ist genau der Ort, den ich gesehen habe.\n\nKommt. Er könnte einen Hinweis darauf bieten, wo meine Mutter abgeblieben ist.", sourceObjective = "Sucht nach Hinweisen auf Tyrande Wisperwind.", completion = "Irgendeine böse Macht an diesem Ort will uns davon abhalten, Tyrande zu finden.\n\nMeiner Erfahrung nach bedeutet das, dass wir auf der richtigen Spur sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[60509] = { id = 60509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mein Job", description = "Also, diese Verschlinger werden bald aus dem Endmorast gekrochen kommen.\n\nUnd die Animadürre setzt die Blutsauger ziemlich unter Druck... Tja, auf jeden Fall werden sie uns nicht helfen, bevor es zu spät ist.\n\nWir Gräber könnten die Hilfe von jemandem wie Euch gut gebrauchen. Professionelle Zerstörer sind gefragt.\n\nTrefft mich im Gräberwald, wenn Ihr es einrichten könnt. Wir trommeln ein paar Leute zusammen und werden versuchen, dagegenzuhalten.", sourceObjective = "Trefft Rendel im Gräberwald.", completion = "Wie ich sehe, habt Ihr Euch entschieden, Euch die Hände dreckig zu machen und uns Arbeiter zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60510] = { id = 60510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgestiegen", description = "Obwohl wir das Erschaffen weiterer Kolosse verhindert haben, atmet eine ihrer scheußlichsten Schöpfungen immer noch. Sie entstand aus einer der gequältesten Seelen, die sie aus meinem Tempel in der Bastion geraubt haben.\n\nWährend ich über ihre Reihen flog, hörte ich, wie die Chirurgen ihren Namen über dem Schlachtenlärm hinweg riefen: Kummerklinge. Blasphemie gegen alles, wofür die Kyrianer stehen, und eine Abscheulichkeit, die jeder Beschreibung spottet.\n\nMarkiert sie mit den Flammen des Mutes, und wir helfen Euch, sie zu zerstören.", sourceObjective = "Tötet Kummerklinge die Abscheulichkeit.", completion = "Möge unser Sieg ihnen Frieden bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60514] = { id = 60514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdtrophäen", description = "Hoffnungsbrecher zu sein bedeutet, jegliche Beute zu besiegen, nicht nur Seelen.\n\nDer Fluchwald ist die Heimat vieler gefährlicher Kreaturen: Todeswandler, Furchtspinner und die schrecklichen Verhängnisreißer. Wenn Ihr die Jagdkunst wirklich beherrschen wollt, solltet Ihr diese Feinde bezwingen können.\n\nBringt mir Trophäen als Beweis für Eure Eroberungen. Dann könnt Ihr Euch vielleicht meinen Respekt verdienen.", sourceObjective = "Sammelt 3 Verhängnisreißerschädel, 3 makellose Todeswandlerpfoten und 3 geschätzte Furchtspinnerfangzähne.", progress = "Habt Ihr die Geschöpfe des Fluchwalds bezwungen?", completion = "<Konstantin untersucht, was Ihr ihm gebracht habt.>\n\nGut gemacht. Vielleicht wird aus Euch noch ein guter Hoffnungsbrecher.", sourceObjectiveStatus = "unverified-source-field" }
quests[60517] = { id = 60517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wegezoll", description = "Dieses Gefäß scheint voller Anima zu sein. Sicherlich handelt es sich dabei um Abgaben, die man von den über diesen Kreuzweg reisenden Bürgern erhebt. Bei allem, was hier vor sich geht, wird Herrin Mihaela in Dunkelhafen es sicherlich begrüßen, wenn ihr diese Abgaben überbracht werden, um die Verpflichtungen des Dorfdistrikts zu decken.", sourceObjective = "Bringt die Abgaben nach Dunkelhafen.\n\nBereitgestellter Gegenstand:", completion = "Was ist das? Der Wegezoll! Varaboss, dieses hinterhältige Scheusal, hat seine Gier noch nie im Griff gehabt. Eure Art bevorzugt dieses Edelmetall als Belohnung, glaube ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[60519] = { id = 60519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz bei der Winterkönigin", description = "Zephyre kündigen die Ankunft der Königin an. Gedämpfte Stille senkt sich über den Hain.\n\nWartet, beobachtet und sprecht, wenn die Zeit gekommen ist.", sourceObjective = "Sprecht mit Mondbeere und wartet auf die Ankunft der Winterkönigin.", progress = "Die Königin muss wegen der Dürre so viel auf sich nehmen. Aber sie ist stark und ich weiß, dass wir die Dürre überstehen werden.", completion = "So schnell verschwunden... Der Wald muss noch schlimmer betroffen sein, als mir klar war.\n\n<Mondbeere wirkt einen Moment lang niedergeschlagen, bevor sie entschlossen ihre Hände in die Hüften stemmt.>\n\nNun, dann müssen wir der Königin eben etwas von ihrer Last abnehmen. Dann wird sie die Zeit haben, Euch eine Audienz zu gewähren!", sourceObjectiveStatus = "unverified-source-field" }
quests[60520] = { id = 60520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraummanifestation", description = "Oh, das ist nicht gut. Gleich nachdem Ihr fort wart, haben sich die Alpträume des Geistes über ganz Tirna Vaal ergossen.\n\nIch habe alles versucht, um sie zu besänftigen. Ich habe versucht, ihr etwas vorzusingen, ich habe es mit Geschichtenerzählen versucht, aber nichts davon scheint sie zu beruhigen.\n\nWürdet Ihr Euch bitte einigen ihrer Alpträume stellen und sie bannen? Das ist vielleicht das Einzige, das etwas bewirken wird.", sourceObjective = "Stellt Euch den Alpträumen des Wildsamens in Tirna Vaal.", progress = "Ihre Träume sind in der Regel wunderschön.", completion = "Na also, das scheint sie beruhigt zu haben. Ich spüre, wie ihr Schlaf sanfter wird.\n\nIhr habt wirklich ein Händchen für so etwas!\n\nAber ich bin besorgt, dass wir uns nur eine Atempause verschafft haben und etwas Drastischeres unternehmen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60521] = { id = 60521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Jagd", description = "Ihr habt schon so viel getan, aber die Königin ist immer noch mit so vielen Dingen im ganzen Wald beschäftigt.\n\nWenn Ihr Eure Botschaft mitteilen wollt, müssen wir ihr etwas von ihrer Last nehmen.\n\nFangen wir mit der Wilden Jagd an. Sie sind die Beschützer des Ardenwaldes. Ihre Reihen wurden im Kampf gegen die Bedrohung der maskierten Fae einigermaßen ausgedünnt.\n\nSprecht mit Jagdhauptmann Korayn am Schimmerkaskadenbecken. Ich habe vor Kurzem gehört, dass ihr Jagdtrupp Verstärkung gebrauchen könnte.\n\nUnd lasst Euch von ihrer Wildheit nicht abschrecken. Solange sie Euch nicht für Beute hält, kann sie sehr nett sein!", sourceObjective = "Sucht Jagdhauptmann Korayn im Schimmerkaskadenbecken auf.", completion = "Lady Mondbeere sagte, sie würde eine starke Hand herschicken, um den Hain zu sichern.\n\nAlso, wie schlagt Ihr Euch im Kampf?", sourceObjectiveStatus = "unverified-source-field" }
quests[60522] = { id = 60522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Tirna Vaal", description = "Wir von der Wilden Jagd sind immer darauf vorbereitet, zur Verteidigung des Ardenwalds in den Zyklus zurückzukehren.\n\nIch muss weiterziehen, und Ihr solltet das auch tun. Ich rate Euch, zu Dromanin Tashmur in Tirna Vaal zurückzukehren. Andere werden Eure Hilfe brauchen.\n\nHier, nehmt dies. Es ist ein Geschenk zum Dank.\n\nUns gegenseitig zu helfen, ist der einzige Weg, diese Dürre zu überleben.", sourceObjective = "Kehrt nach Tirna Vaal zurück.", completion = "Oh, Ihr habt eine Geisterwiege! Das wird wirklich sehr nützlich sein.\n\nVorausgesetzt natürlich, wir können Ruhe in dieses Chaos bringen. Der Wildsamen, mit dem Ihr Euch verbunden habt, durchlebt intensive Alpträume... und sie manifestieren sich überall im Hain!", sourceObjectiveStatus = "unverified-source-field" }
quests[60530] = { id = 60530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Meer der Seelen", description = "Irgendeine Macht hier hält uns davon ab, Tyrande zu finden.\n\nDie Spur aus Leichen scheint in diesen... Strom aus Seelen zu führen.\n\nIch schlage vor, dass wir uns trennen. Ich folge dem Flussufer. Ihr begebt Euch in die Strömung und folgt der Spur.\n\nSolltet Ihr mich brauchen, werde ich in der Nähe sein.\n\nWir werden Tyrande finden, ganz gleich wo dieser Weg uns hinführt.", sourceObjective = "Folgt der Spur aus Leichen zu Tyrande Wisperwind.", completion = "Tyrande muss zur Vernunft kommen. Sie kann die Kaldorei nicht retten, wenn sie weiterhin in dieser Dunkelheit verloren bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60531] = { id = 60531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auserwählte Champions" }
quests[60532] = { id = 60532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dominanz vernichten" }
quests[60533] = { id = 60533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken in Tirna Scithe" }
quests[60534] = { id = 60534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treulose Einwohner" }
quests[60542] = { id = 60542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nathanos Pestrufer" }
quests[60545] = { id = 60545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands: Eine eisige Vorladung", description = "Es ist Zeit, {class};.\n\nHochlord Bolvar Fordragon erbittet Eure Anwesenheit auf der Spitze der Eiskronenzitadelle. Trefft mich in Sturmwind und ich bringe Euch zu ihm.\n\nIch würde ihn nicht warten lassen.", sourceObjective = "Trefft Darion Mograine vor Burg Sturmwind.", completion = "Gut, dass Ihr gekommen seid.\n\nIn dieser dunklen Stunde brauchen wir Helden wie Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[60557] = { id = 60557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erste Mal? Ihr müsst kämpfen!", description = "Wenn es um Kriegsführung geht, ist ein starker Wille genauso ausschlaggebend wie Waffenstärke. Ein demoralisierter Soldat ist ein besiegter Soldat!\n\nWir sind genug an der Zahl, um die Konstrukte mit einem ausgewachsenen Angriff zu überwältigen, aber nur dann, wenn unsere Streitkräfte voll hinter dem Ansturm stehen. Einige werden fallen, aber ihr Opfer wird uns den Sieg sichern!\n\nNehmt dieses Kriegshorn und versammelt unsere Truppen. Erinnert sie an ihre Pflicht gegenüber den Auserwählten!", sourceObjective = "Versammelt 8 demoralisierte Soldaten.", progress = "Habt Ihr die Truppen versammelt?", completion = "Unsere Truppen sind wieder für den Kampf bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[60563] = { id = 60563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildsamen pflegen", description = "Wir reichern diese Wildsamen mit Anima aus den Animazapfen an, die wir in der Umgebung sammeln.\n\nAber die Pfleger der Wildsamen sind verschwunden und einige Wildsamen brauchen Anima.\n\nDas ist eine absolute Schlamperei, die in Ordnung gebracht werden muss, bevor die Winterkönigin eintrifft!\n\nIch habe bereits einen Korb mit Animazapfen gesammelt. Könntet Ihr damit einige der Wildsamen anreichern?\n\nIch zeige Euch, wie es geht, aber dann muss ich mich auf die Suche nach den vermissten Pflegern machen.", sourceObjective = "Sammelt einen Korb mit Animazapfen und benutzt sie dann bei 4 Wildsamen.", completion = "Gute Arbeit. Wir dürfen nicht aufhören, die Wildsamen zu pflegen, die die Winterkönigin zur Rettung auserkoren hat.\n\nVielleicht könntet Ihr mir jetzt noch bei einer anderen Angelegenheit behilflich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60564] = { id = 60564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drei Gorm gehen rein, keiner kommt raus" }
quests[60565] = { id = 60565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Provost für jede Gelegenheit" }
quests[60566] = { id = 60566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Licht", sourceObjective = "Nehmt den Aufzug nach Sündensturz und untersucht das Gelände.", completion = "<Brechfaust ist schwer verletzt.>\n\nZu viele... nicht geschafft...", sourceObjectiveStatus = "unverified-source-field" }
quests[60567] = { id = 60567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildtiere verscheuchen", description = "Hier in den Ruhigen Teichen geht es chaotisch zu. Ich wäre am Boden zerstört, wenn die Winterkönigin das zu Gesicht bekäme.\n\nDas hier sollte ein friedlicher Ort sein, an dem wir Wildsamen mit Anima versorgen.\n\nAber wegen dieser Animadürre nähern darbende Wildtiere sich den Teichen und versuchen, die Anima zu verschlingen.\n\nEs gibt leider keine andere Möglichkeit, als sie zu töten... sonst bringen sie die Geister in den Wildsamen in Gefahr.", sourceObjective = "Tötet 8 animadarbende Wildtiere.", progress = "Ich mache das wirklich ungern, aber wenn ich nur entweder die Tiere verschonen oder die Wildsamen retten kann, muss ich mich für die Wildsamen entscheiden.", completion = "Normalerweise würde ich keine Hilfe von... welchem Volk Ihr auch immer angehört... brauchen.\n\nAch, verzeiht. Das war unhöflich.\n\nIhr müsst verstehen, dass der Ardenwald Seelen aus dem gesamten Reich der Sterblichen beherbergt. Es fällt mir schwer, die richtigen Namen von allen Völkern zu behalten, die hier eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60568] = { id = 60568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TEMP SCHLUNDLAUF", description = "<Platzhalter-Quest. Vielen Dank für Eure Geduld, während unser Entwicklungsteam daran arbeitet, die Schlund-Erfahrung so cool wie möglich zu gestalten. In der Zwischenzeit viel Spaß mit einer Kostprobe eines schnippischen Schwerts und seinem Vorhaben, die vierte Wand zu durchbrechen.>\n\nWisst Ihr, eigentlich würde ich Euch eine Quest geben, um den Schlund zu stürmen und nach Prinz Renathal zu suchen, bevor er in den gefürchteten Torghast, den Turm der Verdammten, gebracht wird.\n\nDa wir dies jedoch NICHT tun können, nehmen wir doch einfach an, wir hätten es getan, und reden mit dieser Projektion von ihm.", sourceObjective = "Sprecht mit der Projektion von Prinz Renathal.", sourceObjectiveStatus = "unverified-source-field" }
quests[60572] = { id = 60572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Geist zuliebe", description = "Mit all der Anima, die Ihr aus Tirna Noch geborgen habt, ist es nur eine Frage der Zeit, bis mein Hain das Ziel aller animasuchenden Feinde des Ardenwalds sein wird.\n\nIch hoffe, Traumweber weiß, was er mit seinem Ritual tut.\n\nIhr müsst schnell handeln. Sprecht mit Traumweber und findet heraus, was zu tun ist, um dem Geist im Wildsamen zu helfen.", sourceObjective = "Sprecht mit Traumweber und bereitet das Ritual vor.", completion = "Ihr seid so weit, das Ritual vorzubereiten? Wunderbar.\n\nIch bin auch bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[60573] = { id = 60573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Fleischklops" }
quests[60574] = { id = 60574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilze schütteln" }
quests[60575] = { id = 60575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Bauch voller Fae", description = "Die hiesige Flora ist während dieser Animadürre irgendwie außer Kontrolle geraten.\n\nDie Pflanzen haben doch tatsächlich die meisten der jungen Fae gefressen, die die Wildsamen hier gepflegt haben.\n\nImmerhin wissen wir jetzt, wo sie die ganze Zeit gewesen sind.\n\nOh, keine Sorge. Das ist nicht zum ersten Mal passiert. Wir können im Inneren dieser Pflanzen eine ganze Weile überdauern.\n\nNehmt meinen Dolch. Benutzt ihn, um das Gestrüpp aufzuschneiden und die anderen Wildsamenpfleger zu befreien.", sourceObjective = "Befreit 16 Wildsamenpfleger aus verschlingenden Hydras.", completion = "Gute Arbeit. Das sollte helfen, damit die Ruhigen Teiche wieder zur Normalität zurückkehren können.\n\nIch gebe zu, dass ich das Schlimmste befürchtet hatte, als ich keine der Pfleger finden konnte. Ich bin froh, dass sie nur von der hiesigen Vegetation verschluckt worden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[60577] = { id = 60577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Appetit auf Animazapfen", description = "Ich muss mich für den Zustand der Ruhigen Teiche entschuldigen. Normalerweise ist es hier recht friedlich.\n\nDie Wildsamenpfleger haben mir erzählt, dass die Pflanzen, die hier herumlaufen, alle Animazapfen gefressen haben, die für Tirna Vaal gedacht waren.\n\nKönntet Ihr diesen Pflanzen vielleicht die Animazapfen abnehmen?\n\nWir haben Wildsamen, die diese Anima benötigen.", sourceObjective = "Holt 25 Animazapfen von Fressblüten zurück.", progress = "Habt Ihr die Animazapfen gefunden? Die sind immer noch nützlich, auch wenn sie ein wenig schleimig sind.\n\nGlaubt mir, den Geistern ist es einerlei, solange sie ihre Anima bekommen.", completion = "Die Animazapfen! In dieser Dürre müssen wir uns auf jedes bisschen Anima stürzen, das wir bekommen können. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[60578] = { id = 60578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Träumerin: Der Verrat", description = "Ich spüre, dass der Geist in seiner Vision mit der Erinnerung an einen wirklich tiefgreifenden Verrat zu kämpfen hat.\n\nJemand, der ihm so nahe stand wie ein Bruder, wurde zu einem Gegner.\n\nGeht zum zweiten Traumschrein im Becken und helft, den Schmerz dieses Alptraums auszulöschen.", sourceObjective = "Ringt mit der Vision der Träumerin über einen großen Verrat.\n\nWenn Ihr die Vision verlasst, könnt Ihr mit dem Portal zur Vision der Träumerin im Traumschreinbecken interagieren, um erneut einzutreten.", completion = "Wie schmerzlich muss es sein, wenn sich ein alter Freund auf die schrecklichste Art und Weise gegen einen wendet.\n\nAber wir sind fast so weit, den Geist in dem Wildsamen zu beruhigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60585] = { id = 60585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruhr der Spriggans" }
quests[60594] = { id = 60594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderer Geist", description = "Ihr habt Tirna Vaal sehr geholfen. Ich muss diese Anima zu einem unserer neuesten Wildsamen bringen.\n\nIch möchte gerne, dass Ihr mich begleitet. Das ist nur gerecht, da Ihr ja schließlich die Animazapfen zurückgeholt habt.\n\nIch freue mich sehr für Euch! Gehen wir.", sourceObjective = "Begleitet Traumweber, um die Wildsamen in Tirna Vaal mit Anima zu nähren.", completion = "Sternenlicht erstrahlt aus Traumweber in einem ruhigen Leuchten.\n\nUnd... zwei Flüsse treffen sich in einer fruchtbaren Mündung. Ein Wildsamen und ein Sterblicher, beide neu im Wald. Von Geist und Schicksal aneinander gebunden.\n\nEs ist lange her, dass das Geäst ein solches Ereignis bezeugt hat. Der Wald wird zusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60597] = { id = 60597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am Gormlingpferch" }
quests[60600] = { id = 60600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung auf die Winterkönigin", description = "Tirna Vaal ist bereit für die Ankunft der Winterkönigin! Und das alles ist Euch zu verdanken.\n\nIhr habt Euren Teil unserer Abmachung mehr als erfüllt... und doch war ich nicht in der Lage, dasselbe zu tun.\n\nDas ist für eine Fee wie mich absolut inakzeptabel! Was würden die anderen denken, wenn sie wüssten, dass ich unsere Abmachung nicht eingehalten habe?\n\nBitte erlaubt mir, es wiedergutzumachen. Ich konnte Eure Botschaft vielleicht nicht der Königin überbringen, aber ich habe eine besondere Überraschung, die Ihr hoffentlich stattdessen annehmen werdet!", sourceObjective = "Nehmt Essenz des Ardenwalds von Lady Mondbeere entgegen.", completion = "Schatten zeichnen sich über dem Herzholzhain ab. Unsichtbare Dinge kriechen in der Dunkelheit umher.", sourceObjectiveStatus = "unverified-source-field" }
quests[60601] = { id = 60601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelschwingendrills" }
quests[60602] = { id = 60602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimdienst" }
quests[60605] = { id = 60605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmerflossenschuppe", description = "<Eine leuchtend bunte Schuppe fällt zu Boden, als der Murloc davonläuft. Er ist anders als jeder andere Murloc, den Ihr in Nordend gesehen habt.\n\nVielleicht weiß König Mrgl-Mrgl mehr über diese neue Art?>", sourceObjective = "Zeigt die Schuppe König Mrgl-Mrgl in der Boreanischen Tundra.", completion = "Was habt Ihr da? Oh! Ist das nicht farbenfroh?\n\nIhr sagt, es gibt eine neue Murlocgruppe im Süden? Das überrascht mich nicht. Mir ist zu Ohren gekommen, dass sich merkwürdige Dinge in den weit entfernten Gewässern ereignet haben.\n\nNun, wenn sie freundlich gesonnen sind, ist es unsere Aufgabe, sie willkommen zu heißen! Hier sind ein paar Tränke, die Ihr wahrscheinlich brauchen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[60606] = { id = 60606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommensgruß für Schimmerbauch", description = "Das Wichtigste zuerst. Wahrscheinlich sind sie hungrig. Das Leben hier oben in der Kälte ist nicht ganz so einfach wie anderswo, und sogar die Murlocs, die am besten an dieses Klima gewöhnt sind, haben manchmal Schwierigkeiten, Nahrung zu finden.\n\nWir müssen sie füttern, ihnen aber auch helfen, selbst Nahrung zu finden.\n\nSie beobachten Euch bereits, also durchsucht die Gegend, in der Ihr auf die Murlocs gestoßen seid, nach Nahrungsquellen und zeigt ihnen, was sie jagen sollen. Dann bringt Ihr das Fleisch zu ihrem Anführer. Sucht einfach nach dem Größten unter ihnen.", sourceObjective = "Sammelt 10 Krabbenfleischbrocken und bringt sie Schimmerbauch in der Venturebucht.", completion = "Mrg?\n\n<Schimmerbauch schaut Euch an, nimmt dann vorsichtig die Krabbenbrocken und reicht sie einem Futterwühler neben sich. Der Futterwühler und Schimmerbauch scheinen ein kurzes Gespräch über Eure Krabbenjagd zu führen.\n\nSchimmerbauch wendet sich Euch wieder zu und zeigt auf den Sand hinunter.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60609] = { id = 60609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer verschlingt die Verschlinger?" }
quests[60614] = { id = 60614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine fette Aufgabe", description = "<Schimmerbauch beginnt, etwas in den Sand zu zeichnen.\n\nDer Murloc zeichnet offenbar die Umrisse einer großen Robbe. Er zeigt auf das Bild, dann nach oben, und deutet an, dass das Wesen irgendwo auf der Wasseroberfläche sein muss.\n\nDann gräbt der Murloc ein kleines, flaches Loch in den Sand und zeigt mehrmals darauf.>\n\nMrg! Mrg! Grml.\n\n<Erwartungsvoll legt er seinen Kopf schief.>", sourceObjective = "Sammelt einen Haufen Tranfett und bringt ihn zu Schimmerbauch in der Venturebucht.", completion = "Grml! Mrgl-rgml. M'gurgel.\n\n<Schimmerbauch schaut die Futterwühler neben sich an. Sie nicken, und er nickt zurück.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60615] = { id = 60615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seherin der Wellen", description = "<Schimmerbauch zeigt quer über das Schiff. Er will, dass Ihr den Tran zu jemandem bringt.>\n\nMrg m'grrl.", sourceObjective = "Bringt das Tranfett zum Schimmerflossenorakel.", completion = "<Das Orakel nimmt Euch das Tranfett ab, als hätte es Eure Ankunft erwartet, und legt es als kleinen Haufen zurecht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60616] = { id = 60616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perle in der Tiefe", description = "<Das Orakel zeichnet einen Kreis in den Sand und zeigt dann nach unten in die Tiefe. Dort unten ist etwas Rundes, das es haben möchte. Vielleicht eine Perle oder ein Stein?\n\nDas Orakel bedeutet Euch, einen Moment zu warten, bevor Ihr geht. Es wedelt hektisch mit den Händen herum, legt sie dann an den Mund und ahmt zwei große Reißzähne nach.\n\nIhr deutet das als Warnung, dass in der eisigen Dunkelheit vielleicht etwas auf Euch wartet.>", sourceObjective = "Holt die riesige Perle und übergebt sie dem Schimmerflossenorakel.", progress = "<Das Orakel schaut Euch an.>", completion = "<Das Orakel nimmt Euch die Perle von Euch entgegen und reibt sie sanft ab, bevor es tief in ihre schimmernden Tiefen blickt>", sourceObjectiveStatus = "unverified-source-field" }
quests[60617] = { id = 60617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test des Lehrers", description = "<Das Orakel beendet seinen Blick in die Perle und dreht sich zu Euch um. Es scheint tief in Gedanken versunken zu sein, starrt Euch direkt an und blinzelt ein paar Mal.\n\nSchließlich nickt es.\n\nDas Orakel zeigt erst auf Euch, dann nach oben. Es hält eine Hand in geringem Abstand über den Boden, was auf etwas Haustiergroßes hindeutet.\n\nIhr vermutet, dass ein Test Eurer Verbindung mit Euren Kampfhaustieren bevorstehen könnte.>", sourceObjective = "Besiegt Lehrer Grrglin in einem Haustierkampf.", completion = "<Das Orakel sieht bei Eurer Rückkehr aufgeregt aus. Es zeigt mehrmals schnell nacheinander auf den Tranhaufen neben sich, in dem ein Ei sanft eingebettet wurde.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60619] = { id = 60619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut eingewickelt", description = "<Das Orakel scheint wegen des neuen Eis ziemlich aufgeregt zu sein. Ihr habt den Eindruck, dass dies ein wichtiger Anlass für diese Murlocs ist. Es sind vielleicht nur noch wenige Eier übrig.\n\nDas Orakel wedelt ein kleines Stück Seetang vor Euch herum und zeigt Euch die frischen Knospen der unreifen Pflanze.\n\nEs wickelt den Seetang um einen kleinen Teil des Eies, zeigt dann auf Euch und dann wieder auf die Seetanghülle.\n\nOffenbar muss das Ei in weitere unreife Seetanghalme gewickelt werden.>", sourceObjective = "Sammelt einen warmen Seetanghalm, einen jungen Seetanghalm und einen knolligen Seetanghalm und gebt sie dem Schimmerflossenorakel.", progress = "<Das Orakel zwinkert Euch zu.>", completion = "<Das Orakel wickelt das Ei sanft in den Seetang ein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60620] = { id = 60620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschützer der Kleinsten", description = "<Das Orakel klopft Euch auf die Schulter und scheint mit allem, was Ihr getan habt, recht zufrieden zu sein.\n\nEs hält einen Finger hoch, breitet dann die Arme aus und gibt ein furchtbares, brüllendes Gegurgel von sich.\n\nEs zeigt nach draußen, dann auf Euch und schließlich auf Eure Waffe und nickt ernst.\n\nEs muss wohl noch eine Prüfung auf Euch warten. Offenbar handelt es sich um ein Kräftemessen.>", sourceObjective = "Tötet den großen Mua'kin und kehrt zum Schimmerflossenorakel zurück.", completion = "<Das Orakel klopft Euch aufgeregt auf die Schulter und hebt triumphierend den Arm.\n\nEs hält inne, zeigt dann schnell auf das Ei und eilt hinüber.\n\nDas Murlocbaby beginnt zu schlüpfen...>", sourceObjectiveStatus = "unverified-source-field" }
quests[60621] = { id = 60621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind vor den Toren", description = "Lorkron ist hier.\n\nIch habe ihn den ganzen Weg von den Funkelnden Fällen bis hierher verfolgt. Dann sah ich, wie die Drust uns in die Flanke fallen wollten.\n\nSie waren ganz schön überrascht, als wir den Spieß umgedreht haben.\n\n<Korayn lächelt grimmig. Sie hebt ihre Waffe und auch ihre Stimme, damit alle Anwesenden sie hören.>\n\nJäger und Jägerinnen, zu mir! Wir reiten, um den Hain zu schützen! Keine Gefangenen und keine Gnade!", sourceObjective = "Erreicht Dromanin Aliothe im Winterschlafbecken.", completion = "Dieser Angriff... Es ist so, als wären sie von irgendetwas besessen!", sourceObjectiveStatus = "unverified-source-field" }
quests[60622] = { id = 60622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge des Sehers", description = "Um den Sehern der Schlundgebundenen entgehen zu können, braucht man mächtige magische Gegenmaßnahmen.\n\nUnd was ist das Hauptreagenz? Ein leuchtendes Auge aus dem Schädel eines Sehers, der kurz zuvor aus seiner Trance erwacht ist.\n\nDie Seherrituale beginnen genau jetzt. Ihr werdet natürlich nur für ein intaktes Auge entlohnt.\n\nBei seiner Beschaffung wird Umsicht empfohlen.", sourceObjective = "Besorgt das Auge des Sehers von Leerok dem Seher im Schlund.", progress = "Nun? Habt Ihr es? Unbeschädigt?", completion = "Meint Ihr, er hat das kommen sehen?\n\nIch habe mich an sterblichem Humor versucht. Ihr dürft gerne lachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60623] = { id = 60623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AAAH! Echte Monster!" }
quests[60624] = { id = 60624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritt zum Herzholzhain", description = "Ein Sturm von Unfrieden und Angst geht auf den Herzholzhain nieder. Sylvar fliehen vor dieser Flut.\n\nTrotzt auf einem Hirsch reitend dem reißenden Strom. Besänftigt die Überschwemmung und seid die Rettung derer, die ertrinken würden.\n\nEilt Euch. Die Zeit vergeht.", sourceObjective = "Reitet auf einem Hirsch zum Herzholzhain.", completion = "Wir können den Herzholzhain nicht in diesem Zustand lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60628] = { id = 60628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vermissten Jäger", description = "Merkwürdige Kreaturen lauern gleich außerhalb des Hains. Schreckliche, hässliche Dinger.\n\nWas immer sie sind... Sie stammen auf jeden Fall nicht aus dem Ardenwald.\n\nAllerdings spielt es keine Rolle, wie sie unsere Grenzen verletzt haben. Jede einzelne von ihnen muss beseitigt werden.\n\nIch habe meine besten Jägerinnen und Jäger ausgeschickt, um sie zu töten, aber keiner von ihnen ist zurückgekehrt. Seht, ob Ihr herausfinden könnt, was sie aufgehalten hat.", sourceObjective = "Findet Jynkla, Serinkai, Rondar und Ara'lon.", completion = "Nur Ara'lon und Lumera haben überlebt? Der Rest ist gefallen?\n\n<Korayn zittert vor ungezügelter Wut.>\n\nIch werde für die Bergung ihrer Leichen sorgen. Und das darf nicht ungestraft bleiben. Wir werden sie alle rächen!", sourceObjectiveStatus = "unverified-source-field" }
quests[60629] = { id = 60629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extreme Wiederverwertung", description = "Die Wilde Jagd dient unter der Leitung von Lord Herne der Winterkönigin. Wir sind Elitekämpfer, Elitejäger und Elitefährtenleser.\n\nAber wir können nicht ohne Waffen und Vorräte kämpfen. Die Dromanin hier hat mir erzählt, dass die hiesige Lieferung stark beeinträchtigt ist.\n\nIch habe keine Zeit zu warten. Wir brauchen Ausrüstung, und zwar jetzt.\n\nSeht, was Ihr vom Schlachtfeld bergen könnt. Eine zerbrochene Waffe kann man immer reparieren und wiederverwenden.", sourceObjective = "Tötet die Verseuchten und nehmt ihre Waffen.", progress = "Habt Ihr da draußen etwas Nützliches gefunden?", completion = "Ihr habt viel mehr Waffen gefunden, als ich erwartet hatte.\n\nSehr seltsam. Wie konnten sie so viele UNSERER Klingen an sich bringen?\n\n<Korayn wirkt besorgt.>\n\nSie werden wieder gegen unsere Feinde zum Einsatz kommen, das schwöre ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[60630] = { id = 60630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemfinsternis", description = "Ich kann die finstere Magie unserer Feinde riechen. Sie verzerrt die Luft und verwirrt meine Gedanken. Sie führen etwas im Schilde. Sie bringen schreckliche Mächte in den Ardenwald.\n\nWenn Ihr ihre Totems seht, dann zerstört sie sofort.\n\nIch fühle mich immer besser, nachdem ich etwas in Stücke geschlagen habe. Ihr nicht auch?", sourceObjective = "Zerstört besudelte Totems.", progress = "Welch furchtbare Magie wurde in den Ardenwald gebracht?", completion = "Bisher war es nicht deutlich, jetzt schon. Dies ist eine persönliche Jagd.\n\nWir werden den Ardenwald von diesem Monster befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[60631] = { id = 60631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großes Problem, kleiner Vorkai", description = "Ara'lons Bericht passt zu dem, was ich gesehen habe. Zu viele Gegner und zu wenige der Wilden Jagd, um sie ohne Unterstützung erledigen zu können.\n\nZum Glück habe ich das starke Bedürfnis, die Angelegenheit selbst in die Hand zu nehmen... und meine gefallenen Jäger zu rächen.\n\nLasst uns aufbrechen. Wir werden diesen Monstern den Zorn der Natur zeigen.", sourceObjective = "Tötet Verseuchte mit Korayn.", progress = "Der Ardenwald wird überdauern.", completion = "Wir haben so viele getötet und trotzdem sind es noch so viele. Wir müssen zum Herzen des Übels vorstoßen und es herausreißen.\n\nWenn nicht, wird sich diese Pest im ganzen Ardenwald ausbreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60632] = { id = 60632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich kenne Euer Gesicht", description = "Diese Stimme... Ich habe sie schon einmal gehört. Obwohl sie jetzt verzerrt und rachsüchtig ist.\n\nEr jagt uns.\n\nAber ich bin kein Beutetier. Und ich werde ihn nicht mit seiner getöteten Beute prahlen lassen. Das ist nicht die Art der Wilden Jagd.\n\nObwohl er uns vielleicht auf ein Gebiet seiner Wahl lockt, werden wir gegen ihn kämpfen.\n\nUnd wir werden gewinnen. Seid Ihr dabei?", sourceObjective = "Besiegt Lorkron den Jäger.", completion = "Es kann nicht leicht für Korayn sein, einen der Unsrigen zu jagen... aber sie hat recht. Der Wald ist nicht sicher, solange Lorkron in ihm lauert.\n\nWelch schreckliches Schicksal... sowohl für alle, die besessen werden, als auch für die, die sie zur Strecke bringen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60637] = { id = 60637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende ehemaliger Freunde", description = "Der Herzholzhain sollte seine Anima aufgeben, damit andere Haine überleben konnten...\n\nAber dann... sah ich immer öfter diese Masken bei vielen der anderen Fae. Bald trugen alle sie.\n\nIch weiß nicht, was über sie gekommen ist, aber es ist klar, dass sie uns schaden wollen. Bitte... Ihr müsst...\n\nSie sind nicht die Freunde, die ich einst kannte. Nicht mehr.", sourceObjective = "Tötet 8 besessene Kreaturen im Herzholzhain.", completion = "Danke. Ich habe mich so bemüht, sie zu retten... Aber sobald sie die Maske aufsetzen, gibt es kein Zurück mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[60638] = { id = 60638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildsamen bergen", description = "Eine meiner Aufgaben im Herzholzhain war es, mich um die Wildsamen zu kümmern.\n\nEinige wurden ausgewählt, um nach Tirna Vaal zurückgebracht zu werden. Aber jetzt entziehen die maskierten Fae ihnen die Anima!\n\nWir müssen die übriggebliebenen retten. Ich flehe Euch an, bergt alle überlebenden Wildsamen, die Ihr finden könnt.\n\nDie Geister in ihrem Inneren wurden dazu auserwählt, wiedergeboren zu werden. Ich werde nicht zulassen, dass sie dahinsiechen!", sourceObjective = "Bergt 6 ausgelaugte Wildsamen im Herzholzhain.", progress = "Wir müssen uns aufteilen und so viele Wildsamen wie möglich retten.", completion = "Ihr habt noch mehr Wildsamen gefunden! Sie sind so schwach... Ich kann es nicht ertragen, sie so zu sehen.\n\nWir müssen hier fertig werden und sie so bald wie möglich nach Tirna Vaal bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60639] = { id = 60639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Hains", description = "Wir sollten das Herz des Hains nach Tirna Vaal bringen, als wir diesen Ort dem Verdorren überließen.\n\nDie maskierten Fae schlugen zu, bevor das geschehen konnte. Sie müssen hinter dem Herz des Hains her sein!\n\nDas Herz enthält all die Anima, die die anderen Haine retten sollte. Wir dürfen sie nicht verlieren.\n\nKönnt Ihr sie sicherstellen? Ich muss Korenth ausfindig machen, einen unserer Heiler. Seine Fähigkeiten werden allen Überlebenden helfen, die wir finden.", sourceObjective = "Bringt das Herz des Hains nach Tirna Vaal.", completion = "Korenth ist... weg? Und das Herz des Hains wurde mitgenommen?\n\nDann... gibt es viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[60640] = { id = 60640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachstum des Hains", description = "Der Hain gedeiht, <mein sterblicher Freund/meine sterbliche Freundin>, aber er hat noch Platz zum Wachsen.\n\nMit genügend Anima kann er noch mehr Wildsamen gleichzeitig nähren. Jeder von ihnen ist ein Geist, der sonst vielleicht für immer verloren wäre.\n\nSprecht noch einmal mit Zayhad, und sorgt für das Nachwachsen des Konservatoriums.", sourceObjective = "Wertet das Konservatorium der Königin auf Stufe 3 auf.", completion = "Eure Bemühungen beleben den Hain und mit ihm unzählige hilfsbedürftige Geister.", sourceObjectiveStatus = "unverified-source-field" }
quests[60641] = { id = 60641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blüte des Hains", description = "Das Konservatorium wird kräftig und gesund. Nun muss es neu erblühen.\n\nObwohl viel Anima benötigt wird, gibt jeder zusätzliche Geist, der durch das Konservatorium wiedergeboren wird, diese Großzügigkeit zehnfach zurück.\n\nBeratet Euch mit Zayhad, damit dieses Konservatorium noch größer wird.", sourceObjective = "Wertet das Konservatorium der Königin auf Stufe 4 auf.", completion = "Die Dankbarkeit dieses Hains ist Euch gewiss. Nun schließen sich vielleicht noch mehr Geister wieder dem Kreislauf an.", sourceObjectiveStatus = "unverified-source-field" }
quests[60642] = { id = 60642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pracht des Hains", description = "Ihr habt viel getan, um dem Konservatorium wieder seinen früheren Glanz zu verleihen.\n\nIn vergangenen Zeiten war dieser Hain ein Ort der Genesung für Geister, die bei ihrem Ableben verwundet wurden und besonderer Pflege bedurften, bevor sie wiedergeboren wurden.\n\nEs war ein Ort, der selten genutzt wurde... aber jetzt ist er entscheidend für die Fortsetzung des Kreislaufs.\n\nSagt Zayhad, dass die Zeit gekommen ist. Das Konservatorium der Königin muss zum Wohle des Ardenwalds gedeihen.", sourceObjective = "Wertet das Konservatorium der Königin auf Stufe 5 auf.", completion = "Das Konservatorium und die Geister, die hier gepflegt werden, stehen für immer in Eurer Schuld.\n\nDanke, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[60644] = { id = 60644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinaus mit der Dunkelheit", description = "Nachdem wir den Dolch endlich haben, braucht es unser aller Willenskraft, um die Verbindung der Waffe zum Oberhäuptling zu trennen.\n\nJaina, Anduin und ich werden alles tun, um Baines Geist stabil zu halten. Ihr allein müsst Euch also um das kümmern, was der Bruch der Klinge entfesselt.\n\nSeid Ihr bereit für diese Aufgabe?", sourceObjective = "Lockt die dahinsiechende Präsenz in Detrithos hervor und vernichtet sie.", completion = "Ohne Eure Hilfe wären mein Körper und Geist wohl auf ewig an diesem von allem verlassenen Ort gefangen gewesen.\n\nIch verdanke Euch mein Leben, {name}. Und ich werde bis zum letzten Atemzug kämpfen, um diese Schuld zu begleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60645] = { id = 60645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gigantischer Sucher" }
quests[60646] = { id = 60646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschäft mit dem Elend", description = "Die Schlundgebundenen haben damit angefangen, das Elend der Seelen zu ernten, die im Gorgoa schwimmen, dem Fluss der Seelen.\n\nWarum? Das weiß ich noch nicht. Aber uns fällt es zu, sie aufzuhalten.\n\nZerstört die Leitungen, in denen sie das Elend lagern, und bringt mir einige Proben ihrer Arbeit. \n\nVielleicht stoße ich mit etwas Nachforschung auf ihr Vohaben.", sourceObjective = "Sammelt 10 Essenzen des Elends und zerstört die Elendsleitungen.", progress = "Habt Ihr ihr Elend beendet?", completion = "Ihr tragt eine große Bürde, aber heute habt Ihr ein paar Seelen vor der Verdammnis gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[60647] = { id = 60647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animazapfen zurückholen", description = "Der Droman des Hains trägt eine der Masken. Ich fürchte, er wird alle Anima aus dem Herz des Hains saugen!\n\nDiese Anima ist für die anderen Haine des Waldes bestimmt. Wenn wir sie verlieren... dann hätten wir den Herzholzhain umsonst verloren...\n\nWir werden einen Weg zum Schleiermoor ebnen, um den Droman zu finden, bevor es zu spät ist.\n\nViele dieser maskierten Fae haben die Anima des Herzholzhains gestohlen. Wir müssen sie unterwegs wiederfinden.\n\nIn dieser Dürre ist jedes Bisschen Anima kostbar.", sourceObjective = "Holt von den Besessenen 25 Animazapfen zurück.", progress = "Wir dürfen nicht zulassen, dass die Besessenen uns noch mehr nehmen.", completion = "So viele Animazapfen verloren... Immerhin konnten wir diese bergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60648] = { id = 60648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebende des Herzholzhains", description = "Korenth... Ich kann nicht glauben, dass er...\n\nWir müssen retten, wen wir können. Droman Krelnor ist zu stark, als dass wir ihm allein gegenübertreten könnten.\n\nIch habe ein paar andere Überlebende gesehen, die im Hain verstreut sind. Beeilung, wir haben keine Zeit zu verlieren!", sourceObjective = "Rettet Casad, Wagenmeisterin Derawyn und Te'zan vor den Besessenen.", progress = "Wir müssen meine Freunde retten!", completion = "Derawyn... Ich darf sie nicht auch noch verlieren! Wir können die Animazapfen verwenden, um sie zu retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[60649] = { id = 60649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dorn in ihrem Auge" }
quests[60651] = { id = 60651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Fleischklops", sourceObjective = "FÜTTERT MICH!", sourceObjectiveStatus = "unverified-source-field" }
